/**
 * Created by nick on 2025-11-21.
 */

import { api, wire } from 'lwc';
import BaseComponent from 'c/baseComponent';

import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';
import getWorkItemTemplates from '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates';
import moveWorkItem from '@salesforce/apex/WorkItemController.moveWorkItem';
import { getFieldValue, getRecord } from 'lightning/uiRecordApi';

import WORK_ITEM_PROJECT_FIELD from '@salesforce/schema/Work_Item__c.Project__c';
import { refreshApex } from '@salesforce/apex';

/* * ======================================================================================
 * SHARED STATE MANAGEMENT (Module Level)
 * This allows all instances of DataManager to share the same data source of truth.
 * ======================================================================================
 */
const PROJECT_DATA_CACHE = {}; // Key: projectId, Value: { workItems: [], statusOptions: [] }
const INSTANCES = new Set(); // Track all active DataManager instances

/**
 * Broadcast data to all DataManager instances for a specific project
 */
const broadcastDataChange = (projectId, data) => {
    // 1. Update Cache
    PROJECT_DATA_CACHE[projectId] = data;

    // 2. Notify all subscribers for this project
    for (const instance of INSTANCES) {
        if (instance.effectiveProjectId === projectId) {
            instance.notifyDataLoaded(data);
        }
    }
};

export default class DataManager extends BaseComponent {
    @api recordId; // Project ID or Work Item ID from record page
    @api objectApiName; // Object type (cgpm__Project__c or cgpm__Work_Item__c)
    @api hierarchyDepth = 3; // Maximum hierarchy depth to load

    projectId; // Resolved Project ID (either from recordId or from Work Item's project lookup)

    connectedCallback() {
        // Register this instance to receive broadcasts
        INSTANCES.add(this);

        // Immediate Check: Do we already have data in memory?
        // If yes, load it immediately to prevent "pop-in" or double loading
        if (this.effectiveProjectId && PROJECT_DATA_CACHE[this.effectiveProjectId]) {
            this.notifyDataLoaded(PROJECT_DATA_CACHE[this.effectiveProjectId]);
        }

        // todo: run wires imperatively, add loading/saving state
    }

    disconnectedCallback() {
        INSTANCES.delete(this);
    }

    get isProjectPage() {
        return this.objectApiName === 'cgpm__Project__c';
    }

    get isWorkItemPage() {
        return this.objectApiName === 'cgpm__Work_Item__c';
    }

    get effectiveProjectId() {
        // On Project page, use recordId directly
        // On Work Item page, use resolved projectId from lookup
        return this.isProjectPage ? this.recordId : (this.projectId ?? undefined);
    }

    get parentWorkItemIdForTemplates() {
        // On Project page: null (top-level templates)
        // On Work Item page: current work item ID (child templates)
        return this.isWorkItemPage ? this.recordId : undefined;
    }

    // Wire to get Work Item record (only when on Work Item page)
    @wire(getRecord, {
        recordId: '$recordId',
        fields: [WORK_ITEM_PROJECT_FIELD]
    })
    wiredWorkItemRecord({ data, error }) {
        if (this.isWorkItemPage) {
            if (data) {
                this.projectId = getFieldValue(data, WORK_ITEM_PROJECT_FIELD);
            } else if (error) {
                this.errorMessage = this.extractErrorMessage(error);
                this.showError(this.errorMessage, 'Error Loading Work Item');
            }
        }
    }

    // Wire to get available work item templates
    @wire(getWorkItemTemplates, {
        projectId: '$effectiveProjectId',
        parentWorkItemId: '$parentWorkItemIdForTemplates'
    })
    wiredTemplates({ data, error }) {
        let templates = [];

        if (data) {
            templates = data;
        } else if (error) {
            console.error('Error loading work item templates:', error);
        }

        this.dispatchEvent(new CustomEvent('templatesload', { detail: { templates } }));
    }

    wiredWorkItemsResult = {};

    // Wire method to load Work Items for the Project (when on Project page)
    @wire(getWorkItemsForProject, {
        projectId: '$effectiveProjectId',
        maxDepth: '$hierarchyDepth'
    })
    wiredWorkItemsForProject(result) {
        if (this.isProjectPage) {
            this.wiredWorkItemsResult = result;
            const { data, error } = result;

            if (error) {
                this.errorMessage = this.extractErrorMessage(error);
                this.showError(this.errorMessage, 'Error Loading Work Items');
                return;
            } else if (!data) {
                this.showError('No Work Items found for this Project', 'Error Loading Work Items');
                return;
            }

            const workItems = data.workItems || [];
            const statusOptions = data.statusOptions || this.defaultStatusOptions;
            const newData = { workItems, statusOptions };

            // DEDUPLICATION LOGIC
            const projectId = this.effectiveProjectId;
            const cached = PROJECT_DATA_CACHE[projectId];

            // Simple string comparison to avoid broadcast loops
            // If data is identical to what we already have, DO NOT broadcast.
            if (cached && JSON.stringify(cached) === JSON.stringify(newData)) {
                return;
            }

            // Update Source of Truth and Notify All
            broadcastDataChange(projectId, newData);
        }
    }

    // Wire method to load Work Item with Children (when on Work Item page)
    @wire(getWorkItemWithChildren, {
        workItemId: '$recordId',
        maxDepth: '$hierarchyDepth'
    })
    wiredWorkItemWithChildren(result) {
        if (this.isWorkItemPage) {
            this.wiredWorkItemsResult = result;
            const { data, error } = result;

            if (error) {
                this.errorMessage = this.extractErrorMessage(error);
                this.showError(this.errorMessage, 'Error Loading Work Item');
                return;
            } else if (!data) {
                this.showError('Work Item not found', 'Error Loading Work Item');
                return;
            }

            const workItems = [data];
            const statusOptions = this.defaultStatusOptions;

            const newData = { workItems, statusOptions };

            // DEDUPLICATION LOGIC
            const contextId = this.recordId;
            const cached = PROJECT_DATA_CACHE[contextId];

            // Simple string comparison to avoid broadcast loops
            // If data is identical to what we already have, DO NOT broadcast.
            if (cached && JSON.stringify(cached) === JSON.stringify(newData)) {
                return;
            }

            // Update Source of Truth and Notify All
            broadcastDataChange(contextId, newData);
        }
    }

    /**
     * Internal method to dispatch the event to the parent
     * Called by the broadcast system or local wire
     */
    @api
    notifyDataLoaded(data) {
        // Defensive copy to prevent mutation bugs
        const detail = JSON.parse(JSON.stringify(data));
        this.dispatchEvent(new CustomEvent('workitemsload', { detail }));
    }

    @api async refresh() {
        try {
            await refreshApex(this.wiredWorkItemsResult);
        } catch (error) {
            this.errorMessage = this.extractErrorMessage(error);
            this.showError(this.errorMessage, 'Error Refreshing');
        }
    }

    @api async moveWorkItem(draggedItemId, targetItemId, draggedParentId, targetParentId) {
        try {
            // Call Apex to reorder
            await moveWorkItem({
                draggedItemId,
                targetItemId,
                draggedParentId,
                targetParentId
            });

            this.showSuccess('Work Items reordered successfully');
        } catch (error) {
            this.errorMessage = this.extractErrorMessage(error);
            this.showError(this.errorMessage, 'Error Reordering Work Items');
        }

        await this.refresh();
    }
}

