import { MessageContext, publish, subscribe, unsubscribe } from 'lightning/messageService';
import { LightningElement, wire } from 'lwc';
import WORK_ITEM_CHANNEL from '@salesforce/messageChannel/WorkItemEventChannel__c';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class BaseComponent extends LightningElement {
    /* Message Service */

    subscription;
    messageContext;

    defaultWorkflow = [
        { name: 'Not Started', variant: 'neutral' },
        { name: 'In Progress', variant: 'warning' },
        { name: 'On Hold', variant: 'inverse' },
        { name: 'Complete', variant: 'success' },
        { name: 'Cancelled', variant: 'error' }
    ];

    defaultStatusOptions = [{ label: 'All Statuses', value: '' }, ...this.defaultWorkflow.map((status) => ({ label: status.name, value: status.name }))];

    @wire(MessageContext)
    wiredMessageContext(result) {
        this.messageContext = result;
        if (this.messageContext && !this.subscription) {
            this.subscribeToMessageChannel;
        }
    }

    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromMessageChannel();
    }

    // Message Service subscription
    subscribeToMessageChannel() {
        if (!this.subscription) {
            this.subscription = subscribe(this.messageContext, WORK_ITEM_CHANNEL, (message) => this.handleMessage(message));
        }
    }

    unsubscribeFromMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    /**
     * @param {{ action: string; details: object }} message - The message received from the channel
     */
    handleMessage(message) {
        switch (message.action) {
            case 'foo':
                break;

            default:
            // Do nothing for other messages
        }
    }

    /**
     * @param {string} action - The action type to notify about, will be mixed into the details
     * @param {object} details - Additional details to send with the message
     */
    notify(action, details = {}) {
        publish(this.messageContext, WORK_ITEM_CHANNEL, {
            action: action,
            ...{ action, ...details }
        });
    }

    /* Local Storage Helpers */

    /**
     * Save a specific setting for a specific context (e.g., ProjectId)
     * @param {string} contextId - The Project ID or unique record ID
     * @param {string} key - The specific setting name (e.g., 'activeTab')
     * @param {any} value - The value to store
     */
    setLocalState(contextId, key, value) {
        if (!contextId) {
            return;
        }

        const storageKey = `cgpm_prefs_${contextId}`;

        try {
            // 1. Get existing object or create new
            const existingData = JSON.parse(localStorage.getItem(storageKey)) || {};

            // 2. Update specific key
            existingData[key] = value;

            // 3. Save back
            localStorage.setItem(storageKey, JSON.stringify(existingData));
        } catch (e) {
            console.warn('Local storage failed (Quota or Private Mode):', e);
        }
    }

    /**
     * Load a setting
     * @param {string} contextId - The Project ID
     * @param {string} key - The setting name
     * @param {any} defaultValue - Value to return if nothing is saved
     */
    getLocalState(contextId, key, defaultValue) {
        if (!contextId) {
            return defaultValue;
        }

        const storageKey = `cgpm_prefs_${contextId}`;

        try {
            const data = JSON.parse(localStorage.getItem(storageKey));
            // Return saved value if it exists, otherwise default
            return data && data[key] !== undefined ? data[key] : defaultValue;
        } catch (e) {
            return defaultValue;
        }
    }

    /* Toast Helpers */

    /**
     * @param {string|null} message
     * @param {string|"Success"} title
     */
    showSuccess(message, title = 'Success') {
        this.dispatchEvent(
            new ShowToastEvent({
                title,
                message,
                variant: 'success'
            })
        );
    }

    /**
     * @param {string|null} message
     * @param {string|"Error"} title
     */
    showError(message, title = 'Error') {
        this.dispatchEvent(
            new ShowToastEvent({
                title,
                message,
                variant: 'error',
                mode: 'sticky'
            })
        );
    }

    /**
     * @param {string|null} message
     * @param {string|"Warning"} title
     */
    showWarning(message, title = 'Warning') {
        this.dispatchEvent(
            new ShowToastEvent({
                title,
                message,
                variant: 'warning'
            })
        );
    }

    /**
     * @param {string|null} message
     * @param {string|"Info"} title
     */
    showInfo(message, title = 'Info') {
        this.dispatchEvent(
            new ShowToastEvent({
                title,
                message,
                variant: 'info'
            })
        );
    }

    /**
     * Extract user-friendly error message from error object
     */
    extractErrorMessage(error) {
        if (Array.isArray(error.body)) {
            return error.body.map((e) => e.message).join(', ');
        } else if (error.body && typeof error.body.message === 'string') {
            return error.body.message;
        }
        return 'An unknown error occurred.';
    }
}

