import { api, track } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import BaseComponent from 'c/baseComponent';

export default class WorkItemCardContainer extends BaseComponent {
    @api recordId; // Project ID or Work Item ID from record page
    @api hierarchyDepth = 3; // Maximum hierarchy depth to load
    @api objectApiName; // Object type (cgpm__Project__c or cgpm__Work_Item__c)

    @track workItems = [];
    @track filteredWorkItems = [];
    @track expandedStates = {}; // Track expanded/collapsed state by work item ID
    @track availableTemplates = []; // Available work item templates

    viewMode = 'compact'; // View mode: 'compact', 'detailed', or 'timeline' (default to compact)
    statusFilter = '';
    _isLoading = false;
    errorMessage = '';
    wiredWorkItemsResult; // Store wired result for refreshing
    projectId; // Resolved Project ID (either from recordId or from Work Item's project lookup)

    // Status picklist options
    statusOptions = this.defaultStatusOptions;

    connectedCallback() {
        this.viewMode = this.getLocalState(this.recordId, 'WorkItemCardContainer.viewMode', this.viewMode);
    }

    handleTemplatesLoad(event) {
        this.availableTemplates = event.detail.templates;
    }

    /**
     * Handle wired data from either method
     */
    handleWorkItemsLoad(event) {
        const { workItems, statusOptions } = event.detail;

        this.workItems = this.processWorkItems(workItems);
        this.statusOptions = statusOptions || this.statusOptions;
        this.applyFilter();
        this.isLoading = false;
        this.errorMessage = '';
    }

    /**
     * Process work items from Apex to add UI state properties
     */
    processWorkItems(workItems) {
        return workItems.map((item) => {
            const processed = { ...item };
            // Initialize expanded state (default: expand up to 3rd level - depth 0, 1, 2)
            processed.isExpanded = this.expandedStates[item.id] !== undefined ? this.expandedStates[item.id] : item.depth < 3;

            // Recursively process children
            if (item.children && item.children.length > 0) {
                processed.children = this.processWorkItems(item.children);
            }

            return processed;
        });
    }

    /**
     * Get all work items flattened (for blocker picklist)
     */
    get allWorkItemsFlat() {
        const flatten = (items) => {
            let result = [];
            for (const item of items) {
                result.push({ id: item.id, name: item.name });
                if (item.children && item.children.length > 0) {
                    result = result.concat(flatten(item.children));
                }
            }
            return result;
        };

        return flatten(this.workItems);
    }

    /**
     * Apply status filter to work items
     */
    applyFilter() {
        if (this.statusFilter) {
            this.filteredWorkItems = this.workItems.filter((item) => this.matchesFilter(item, this.statusFilter));
        } else {
            this.filteredWorkItems = [...this.workItems];
        }
    }

    /**
     * Recursively check if work item or any of its children match the filter
     */
    matchesFilter(item, status) {
        // Check if this item matches
        if (item.status === status) {
            return true;
        }

        // Check if any children match
        if (item.children && item.children.length > 0) {
            return item.children.some((child) => this.matchesFilter(child, status));
        }

        return false;
    }

    /**
     * Handle messages from Lightning Message Service
     */
    handleMessage(message) {
        super.handleMessage(message);

        // Refresh for created/deleted items
        if (message.action === 'workItemCreated' || message.action === 'workItemDeleted') {
            if (!message.keepModalOpen) {
                this.refs.dataManager.refresh();
            }
            return;
        }

        // Refresh action - always refresh
        if (message.action === 'refresh') {
            if (!message.keepModalOpen) {
                this.refs.dataManager.refresh();
            }
            return;
        }

        // For updates, refresh if not from gantt
        if (message.action === 'workItemUpdated') {
            if (!message.keepModalOpen) {
                this.refs.dataManager.refresh();
            }
            return;
        }

        // Open history modal
        if (message.action === 'openHistoryModal') {
            const modal = this.template.querySelector('c-work-item-history-modal');
            if (modal) {
                modal.openModal(message.workItemId); // todo: use standard modals
            }
        }
    }

    // === Event Handlers ===

    /**
     * Handle status filter change
     */
    handleStatusFilterChange(event) {
        this.statusFilter = event.detail.value;
        this.applyFilter();
    }

    /**
     * Handle refresh button click
     */
    // todo: add isloading event
    async handleRefresh() {
        this.isLoading = true;
        try {
            await refreshApex(this.wiredWorkItemsResult);
            this.isLoading = false;
        } catch (error) {
            this.isLoading = false;
            this.errorMessage = this.extractErrorMessage(error);
            this.showError(this.errorMessage, 'Error Refreshing');
        }
    }

    /**
     * Handle new work item button click
     */
    handleNewWorkItem() {
        // Open create modal for top-level work item
        const modal = this.template.querySelector('c-work-item-create-modal');
        if (modal) {
            modal.open(); // todo: use standard modals
        }
    }

    /**
     * Handle work item created event
     */
    handleWorkItemCreated() {
        // Refresh work items list
        //this.loadWorkItems();
        this.refs.dataManager.refresh();
    }

    /**
     * Handle expand all button click
     */
    handleExpandAll() {
        this.updateAllExpandedStates(this.workItems, true);
        this.filteredWorkItems = this.processWorkItems(this.workItems);
    }

    /**
     * Handle collapse all button click
     */
    handleCollapseAll() {
        this.updateAllExpandedStates(this.workItems, false);
        this.filteredWorkItems = this.processWorkItems(this.workItems);
    }

    /**
     * Recursively update expanded states for all work items
     */
    updateAllExpandedStates(items, isExpanded) {
        items.forEach((item) => {
            this.expandedStates[item.id] = isExpanded;
            if (item.children && item.children.length > 0) {
                this.updateAllExpandedStates(item.children, isExpanded);
            }
        });
    }

    /**
     * Handle work item update event from child component
     */
    handleWorkItemUpdate(event) {
        const { workItemId, changes, keepModalOpen, suppressToast } = event.detail;

        // Publish message to other components (including keepModalOpen flag)
        this.notify('workItemUpdated', { workItemId, changes, keepModalOpen, projectId: this.effectiveProjectId });

        // Show success toast (skip if suppressToast or keepModalOpen is true to avoid duplicate toasts)
        if (!keepModalOpen && !suppressToast) {
            this.showSuccess('Work item updated successfully');
        }

        // Only refresh data if modal doesn't need to stay open
        // When modal is open, skip refresh to prevent modal from closing
        if (!keepModalOpen) {
            this.refs.dataManager.refresh();
        }
    }

    /**
     * Handle work item expand event from child component
     */
    handleWorkItemExpand(event) {
        const { workItemId } = event.detail;
        this.expandedStates[workItemId] = true;
        this.filteredWorkItems = this.processWorkItems(this.workItems);

        // Publish message
        this.notify('workItemExpanded', { workItemId, projectId: this.effectiveProjectId });
    }

    /**
     * Handle work item collapse event from child component
     */
    handleWorkItemCollapse(event) {
        const { workItemId } = event.detail;
        this.expandedStates[workItemId] = false;
        this.filteredWorkItems = this.processWorkItems(this.workItems);

        // Publish message
        this.notify('workItemCollapsed', { workItemId, projectId: this.effectiveProjectId });
    }

    /**
     * Handle action executed event from child component
     */
    handleActionExecuted(event) {
        const { actionName } = event.detail;
        this.showInfo(`Action "${actionName}" executed on work item`, 'Action Executed');
    }

    /**
     * Handle view mode button click
     */
    handleViewMode(event) {
        this.viewMode = event.target.value;
        this.setLocalState(this.recordId, 'WorkItemCardContainer.viewMode', this.viewMode);
    }

    async handleReorder(event) {
        const { draggedItemId, targetItemId, draggedParentId, targetParentId } = event.detail;

        try {
            this.isLoading = true;

            this.refs.dataManager.moveWorkItem(draggedItemId, targetItemId, draggedParentId, targetParentId);
        } catch (error) {
            this.showError(error.body?.message || error.message || 'Unknown error', 'Error reordering work items');
        } finally {
            this.isLoading = false;
        }
    }

    // === Computed Properties ===

    get isLoading() {
        return this._isLoading;
    }

    set isLoading(value) {
        this._isLoading = value;
    }

    get hasError() {
        return this.errorMessage && this.errorMessage.length > 0;
    }

    get hasWorkItems() {
        return !this.isLoading && !this.hasError && this.filteredWorkItems && this.filteredWorkItems.length > 0;
    }

    get hasNoWorkItems() {
        return !this.isLoading && !this.hasError && (!this.filteredWorkItems || this.filteredWorkItems.length === 0);
    }

    get isProjectPage() {
        return this.objectApiName === 'cgpm__Project__c';
    }

    get isWorkItemPage() {
        return this.objectApiName === 'cgpm__Work_Item__c';
    }

    get effectiveProjectId() {
        // On Project page, use recordId directly
        // On Work Item page, use resolved projectId from lookup
        return this.isProjectPage ? this.recordId : this.projectId;
    }

    get compactButtonVariant() {
        return this.viewMode === 'compact' ? 'brand' : 'neutral';
    }

    get detailedButtonVariant() {
        return this.viewMode === 'detailed' ? 'brand' : 'neutral';
    }

    get timelineButtonVariant() {
        return this.viewMode === 'timeline' ? 'brand' : 'neutral';
    }

    get hasAvailableTemplates() {
        return this.availableTemplates && this.availableTemplates.length > 0;
    }

    get showAddButton() {
        return this.hasAvailableTemplates;
    }

    get parentWorkItemIdForTemplates() {
        // On Project page: null (top-level templates)
        // On Work Item page: current work item ID (child templates)
        return this.isWorkItemPage ? this.recordId : null;
    }

    get showWorkItemsList() {
        return this.viewMode === 'compact' || this.viewMode === 'detailed';
    }

    get showTimelineView() {
        return this.viewMode === 'timeline';
    }
}

