    19→import BLOCKER_WORK_ITEM_FIELD from '@salesforce/schema/Work_Item__c.Blocker_Work_Item__c';
    20→
    21→export default class WorkItemCard extends NavigationMixin(DraggableComponent) {
    22→    @api workItem; // Work Item wrapper object from Apex
    23→    @api allWorkItems = []; // All work items in the project for blocker picklist (deprecated - using wire instead)
    24→    @api level = 0; // Hierarchy level (0 = root, 1 = child, etc.)
    25→    @api isExpanded = false; // Expanded/collapsed state
    26→    @api viewMode = 'detailed'; // View mode: 'compact' or 'detailed'
    27→
    28→    /**
    29→     * Handle messages from Lightning Message Service
    30→     */
    31→    handleMessage(message) {
    32→        super.handleMessage(message);
    33→
    34→        switch (message.action) {
    35→            case 'workItemStatusOpened':
    36→                if (message.workItemId !== this.workItem.id) {
    37→                    this.showStatusDropdown = false;
    38→                }
    39→                break;
    40→
    41→            default:
    42→            // Do nothing for other messages
    43→        }
    44→    }
    45→
    46→    // Wire to get all work item options for the project
    47→    workItemOptions = [];
    48→    @wire(getWorkItemOptionsForProject, { projectId: '$workItem.projectId' })
    49→    wiredWorkItemOptions({ data, error }) {
    50→        if (data) {
    51→            this.workItemOptions = data;
    52→        } else if (error) {
    53→            console.error('Error loading work item options:', error);
    54→            this.workItemOptions = [];
    55→        }
    56→    }
    57→
    58→    // Wire to get count of allowed child types for this work item's template
    59→    allowedChildTypeCount = 0;
    60→    @wire(getAllowedChildTypeCount, { workItemTemplateId: '$workItem.templateId' })
    61→    wiredAllowedChildTypeCount({ data, error }) {
    62→        if (data !== undefined && data !== null) {
    63→            this.allowedChildTypeCount = data;
    64→        } else if (error) {
    65→            console.error('Error loading allowed child type count:', error);
    66→            this.allowedChildTypeCount = 0;
    67→        }
    68→    }
    69→
    70→    // Status dropdown state
    71→    showStatusDropdown = false;
    72→
    73→    // Edit mode state
    74→    isEditMode = false;
    75→
    76→    // Edit form values
    77→    editName = '';
    78→    editSummary = '';
    79→    editNextSteps = '';
    80→    editStartDate = '';
    81→    editDueDate = '';
    82→    editEstimatedHours = null;
    83→
    84→    // At Risk modal state
    85→    showAtRiskModal = false;
    86→    atRiskChecked = false;
    87→    atRiskDetailsValue = '';
    88→
    89→    // Blocked modal state
    90→    showBlockedModal = false;
    91→    blockedChecked = false;
    92→    blockedDetailsValue = '';
    93→    blockerWorkItemId = null;
    94→
    95→    // Delete modal state
    96→    showDeleteModal = false;
    97→    isDeleting = false;
    98→
    99→    /**
   100→     * Component lifecycle - add click outside listener
   101→     */
   102→    connectedCallback() {
   103→        document.addEventListener('click', this.handleClickOutside.bind(this));
   104→    }
   105→
   106→    /**
   107→     * Component lifecycle - remove click outside listener
   108→     */
   109→    disconnectedCallback() {
   110→        document.removeEventListener('click', this.handleClickOutside);
   111→    }
   112→
   113→    handleCardClick(event) {
   114→        this.notify('activateWorkItem', {
   115→            workItemId: event.target.dataset.workItemId
   116→        });
   117→    }
   118→
   119→    /**
   120→     * Handle clicks outside the dropdown to close it
   121→     */
   122→    handleClickOutside(event) {
   123→        const dropdown = this.template.querySelector('.status-dropdown-container');
   124→        if (dropdown && !dropdown.contains(event.target)) {
   125→            this.showStatusDropdown = false;
   126→        }
   127→    }
   128→
   129→    /**
   130→     * Handle toggle expand/collapse
   131→     */
   132→    handleToggleExpand() {
   133→        const eventName = this.isExpanded ? 'workitemcollapse' : 'workitemexpand';
   134→        const event = new CustomEvent(eventName, {
   135→            detail: {
   136→                workItemId: this.workItem.id
   137→            },
   138→            bubbles: true,
   139→            composed: true
   140→        });
   141→        this.dispatchEvent(event);
   142→    }
   143→
   144→    /**
   145→     * Stop event propagation (prevent clicks on input fields from toggling expand/collapse)
   146→     */
   147→    handleStopPropagation(event) {
   148→        event.stopPropagation();
   149→    }
