   823→    /**
   824→     * Status options for dropdown
   825→     */
   826→    get statusOptions() {
   827→        let workflow = this.workItem.workflow;
   828→
   829→        if (!workflow || !workflow.some((status) => status.name === this.workItem.status)) {
   830→            workflow = this.defaultWorkflow;
   831→        }
   832→
   833→        // If no transitions defined, return all statuses
   834→        if (!this.workItem.hasTransitions) {
   835→            return workflow.map((status) => ({ label: status.name, value: status.name }));
   836→        }
   837→
   838→        // Find current status and return its transitions
