import { api, wire } from 'lwc';
import DraggableComponent from 'c/draggableComponent';
import { NavigationMixin } from 'lightning/navigation';
import { updateRecord, deleteRecord } from 'lightning/uiRecordApi';
import getWorkItemOptionsForProject from '@salesforce/apex/WorkItemController.getWorkItemOptionsForProject';
import getAllowedChildTypeCount from '@salesforce/apex/WorkItemController.getAllowedChildTypeCount';
import ID_FIELD from '@salesforce/schema/Work_Item__c.Id';
import STATUS_FIELD from '@salesforce/schema/Work_Item__c.Status__c';
import NAME_FIELD from '@salesforce/schema/Work_Item__c.Work_Item_Name__c';
import SUMMARY_FIELD from '@salesforce/schema/Work_Item__c.Summary__c';
import NEXT_STEPS_FIELD from '@salesforce/schema/Work_Item__c.Next_Steps__c';
import START_DATE_FIELD from '@salesforce/schema/Work_Item__c.Start_Date__c';
import DUE_DATE_FIELD from '@salesforce/schema/Work_Item__c.Due_Date__c';
import ESTIMATED_HOURS_FIELD from '@salesforce/schema/Work_Item__c.Estimated_Hours__c';
import AT_RISK_FIELD from '@salesforce/schema/Work_Item__c.At_Risk__c';
import AT_RISK_DETAILS_FIELD from '@salesforce/schema/Work_Item__c.At_Risk_Details__c';
import BLOCKED_FIELD from '@salesforce/schema/Work_Item__c.Blocked__c';
import BLOCKED_DETAILS_FIELD from '@salesforce/schema/Work_Item__c.Blocked_Details__c';
import BLOCKER_WORK_ITEM_FIELD from '@salesforce/schema/Work_Item__c.Blocker_Work_Item__c';

export default class WorkItemCard extends NavigationMixin(DraggableComponent) {
    @api workItem; // Work Item wrapper object from Apex
    @api allWorkItems = []; // All work items in the project for blocker picklist (deprecated - using wire instead)
    @api level = 0; // Hierarchy level (0 = root, 1 = child, etc.)
    @api isExpanded = false; // Expanded/collapsed state
    @api viewMode = 'detailed'; // View mode: 'compact' or 'detailed'

    /**
     * Handle messages from Lightning Message Service
     */
    handleMessage(message) {
        super.handleMessage(message);

        switch (message.action) {
            case 'workItemStatusOpened':
                if (message.workItemId !== this.workItem.id) {
                    this.showStatusDropdown = false;
                }
                break;

            default:
            // Do nothing for other messages
        }
    }

    // Wire to get all work item options for the project
    workItemOptions = [];
    @wire(getWorkItemOptionsForProject, { projectId: '$workItem.projectId' })
    wiredWorkItemOptions({ data, error }) {
        if (data) {
            this.workItemOptions = data;
        } else if (error) {
            console.error('Error loading work item options:', error);
            this.workItemOptions = [];
        }
    }

    // Wire to get count of allowed child types for this work item's template
    allowedChildTypeCount = 0;
    @wire(getAllowedChildTypeCount, { workItemTemplateId: '$workItem.templateId' })
    wiredAllowedChildTypeCount({ data, error }) {
        if (data !== undefined && data !== null) {
            this.allowedChildTypeCount = data;
        } else if (error) {
            console.error('Error loading allowed child type count:', error);
            this.allowedChildTypeCount = 0;
        }
    }

    // Status dropdown state
    showStatusDropdown = false;

    // Edit mode state
    isEditMode = false;

    // Edit form values
    editName = '';
    editSummary = '';
    editNextSteps = '';
    editStartDate = '';
    editDueDate = '';
    editEstimatedHours = null;

    // At Risk modal state
    showAtRiskModal = false;
    atRiskChecked = false;
    atRiskDetailsValue = '';

    // Blocked modal state
    showBlockedModal = false;
    blockedChecked = false;
    blockedDetailsValue = '';
    blockerWorkItemId = null;

    // Delete modal state
    showDeleteModal = false;
    isDeleting = false;

    /**
     * Component lifecycle - add click outside listener
     */
    connectedCallback() {
        document.addEventListener('click', this.handleClickOutside.bind(this));
    }

    /**
     * Component lifecycle - remove click outside listener
     */
    disconnectedCallback() {
        document.removeEventListener('click', this.handleClickOutside);
    }

    handleCardClick(event) {
        this.notify('activateWorkItem', {
            workItemId: event.target.dataset.workItemId
        });
    }

    /**
     * Handle clicks outside the dropdown to close it
     */
    handleClickOutside(event) {
        const dropdown = this.template.querySelector('.status-dropdown-container');
        if (dropdown && !dropdown.contains(event.target)) {
            this.showStatusDropdown = false;
        }
    }

    /**
     * Handle toggle expand/collapse
     */
    handleToggleExpand() {
        const eventName = this.isExpanded ? 'workitemcollapse' : 'workitemexpand';
        const event = new CustomEvent(eventName, {
            detail: {
                workItemId: this.workItem.id
            },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(event);
    }

    /**
     * Stop event propagation (prevent clicks on input fields from toggling expand/collapse)
     */
    handleStopPropagation(event) {
        event.stopPropagation();
    }

    /**
     * Handle navigation to Work Item record page
     */
    handleNavigateToRecord(event) {
        // Prevent event from bubbling up to toggle expand/collapse
        event.preventDefault();
        event.stopPropagation();

        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: this.workItem.id,
                objectApiName: 'cgpm__Work_Item__c',
                actionName: 'view'
            }
        });
    }

    /**
     * Handle opening time log modal
     */
    handleOpenTimeEntries(event) {
        event.preventDefault();
        event.stopPropagation();

        const modal = this.template.querySelector('c-time-log-modal');
        if (modal) {
            modal.openModal();
        }
    }

    /**
     * Handle time logged event - refresh work item data
     */
    handleTimeLogged(event) {
        // Publish refresh event so parent component can reload work items
        this.notify('refresh', { workItemId: this.workItem.id });
    }

    /**
     * Handle opening resource assignment modal
     */
    handleOpenResourceModal(event) {
        event.preventDefault();
        event.stopPropagation();

        const modal = this.template.querySelector('c-resource-assignment-modal');
        if (modal) {
            modal.open();
        }
    }

    /**
     * Handle work item data refreshed from modal
     */
    handleWorkItemDataRefreshed(event) {
        // Update the local work item data with refreshed data from server
        const updatedWorkItem = event.detail.workItem;

        // Update specific fields that may have changed
        if (updatedWorkItem) {
            this.workItem = {
                ...this.workItem,
                ownerName: updatedWorkItem.ownerName,
                ownerId: updatedWorkItem.ownerId,
                assignments: updatedWorkItem.assignments
            };
        }
    }

    /**
     * Handle modal closed - trigger full refresh of work items
     */
    handleModalClosed(event) {
        // Dispatch event to parent to refresh all work item data
        const refreshEvent = new CustomEvent('workitemupdate', {
            detail: {
                workItemId: event.detail.workItemId,
                keepModalOpen: false
            },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(refreshEvent);
    }

    /**
     * Handle action executed from action bar
     */
    handleActionExecuted(event) {
        // Check if this is an Edit action
        if (event.detail.actionName === 'Edit') {
            // Enter edit mode
            this.handleEdit(event);
        } else if (event.detail.actionName === 'Add Note') {
            // Open note modal
            this.handleOpenNoteModal(event);
        } else if (event.detail.actionName === 'Add Child') {
            // Open create modal for child work item
            this.handleOpenCreateModal(event);
        } else if (event.detail.actionName === 'Delete') {
            // Open delete confirmation modal
            this.handleOpenDeleteModal(event);
        } else {
            // Bubble event up to parent for other actions
            const bubbledEvent = new CustomEvent('actionexecuted', {
                detail: event.detail,
                bubbles: true,
                composed: true
            });
            this.dispatchEvent(bubbledEvent);
        }
    }

    /**
     * Handle opening note modal
     */
    handleOpenNoteModal(event) {
        event.preventDefault();
        event.stopPropagation();

        const modal = this.template.querySelector('c-work-item-note-modal');
        if (modal) {
            modal.open();
        }
    }

    /**
     * Handle note created event
     */
    handleNoteCreated(event) {
        // Dispatch update event to parent to refresh data
        const updateEvent = new CustomEvent('workitemupdate', {
            detail: {
                workItemId: event.detail.workItemId
            },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(updateEvent);
    }

    /**
     * Handle opening create modal for child work item
     */
    handleOpenCreateModal(event) {
        event.preventDefault();
        event.stopPropagation();

        const modal = this.template.querySelector('c-work-item-create-modal');
        if (modal) {
            modal.open({
                parentWorkItemId: this.workItem.id,
                parentWorkItemName: this.workItem.name
            });
        }
    }

    /**
     * Handle work item created event
     */
    handleWorkItemCreated(event) {
        // Dispatch update event to parent to refresh data
        const updateEvent = new CustomEvent('workitemupdate', {
            detail: {
                workItemId: event.detail.parentWorkItemId || this.workItem.id
            },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(updateEvent);
    }

    /**
     * Handle child update event (from nested work item cards)
     */
    handleChildUpdate(event) {
        // Bubble event up to parent
        const bubbledEvent = new CustomEvent('workitemupdate', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    /**
     * Handle child expand event
     */
    handleChildExpand(event) {
        // Bubble event up to parent
        const bubbledEvent = new CustomEvent('workitemexpand', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    /**
     * Handle child collapse event
     */
    handleChildCollapse(event) {
        // Bubble event up to parent
        const bubbledEvent = new CustomEvent('workitemcollapse', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    /**
     * Handle child action executed event
     */
    handleChildActionExecuted(event) {
        // Bubble event up to parent
        const bubbledEvent = new CustomEvent('actionexecuted', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    /**
     * Handle opening history modal via Lightning Message Service
     */
    handleOpenHistory() {
        this.notify('openHistoryModal', { workItemId: this.workItem.id, workItemName: this.workItem.name });
    }

    /**
     * Handle Edit button click - enter edit mode
     */
    handleEdit(event) {
        event.preventDefault();
        event.stopPropagation();

        // Initialize edit values from current work item
        this.editName = this.workItem.name;
        this.editSummary = this.workItem.description || '';
        this.editNextSteps = this.workItem.nextSteps || '';
        this.editStartDate = this.workItem.startDate || '';
        this.editDueDate = this.workItem.dueDate || '';
        this.editEstimatedHours = this.workItem.estimatedHours || null;

        this.isEditMode = true;
    }

    /**
     * Handle Cancel button click - exit edit mode
     */
    handleCancelEdit(event) {
        event.preventDefault();
        event.stopPropagation();

        this.isEditMode = false;
    }

    /**
     * Handle Save button click - save changes
     */
    async handleSaveEdit(event) {
        event.preventDefault();
        event.stopPropagation();

        try {
            const fields = {};
            fields[ID_FIELD.fieldApiName] = this.workItem.id;
            fields[NAME_FIELD.fieldApiName] = this.editName;
            fields[SUMMARY_FIELD.fieldApiName] = this.editSummary;
            fields[NEXT_STEPS_FIELD.fieldApiName] = this.editNextSteps;
            fields[START_DATE_FIELD.fieldApiName] = this.editStartDate || null;
            fields[DUE_DATE_FIELD.fieldApiName] = this.editDueDate || null;
            fields[ESTIMATED_HOURS_FIELD.fieldApiName] = this.editEstimatedHours || null;

            const recordInput = { fields };
            await updateRecord(recordInput);

            // Exit edit mode
            this.isEditMode = false;

            // Show success toast
            this.showSuccess('Work item updated successfully');

            // Dispatch update event to parent to refresh data
            const updateEvent = new CustomEvent('workitemupdate', {
                detail: {
                    workItemId: this.workItem.id
                },
                bubbles: true,
                composed: true
            });
            this.dispatchEvent(updateEvent);
        } catch (error) {
            console.error('Error updating work item:', error);
            this.showError(error.body?.message || 'Error updating work item');
        }
    }

    /**
     * Handle input changes for edit fields
     */
    handleFieldChange(event) {
        const fieldName = event.target.dataset.field;
        const value = event.target.value;

        switch (fieldName) {
            case 'name':
                this.editName = value;
                break;
            case 'summary':
                this.editSummary = value;
                break;
            case 'nextSteps':
                this.editNextSteps = value;
                break;
            case 'startDate':
                this.editStartDate = value;
                break;
            case 'dueDate':
                this.editDueDate = value;
                break;
            case 'estimatedHours':
                this.editEstimatedHours = value;
                break;
        }
    }

    /**
     * Handle status badge click
     */
    handleStatusClick(event) {
        event.preventDefault();
        event.stopPropagation();

        this.notify('workItemStatusOpened', { workItemId: this.workItem.id });

        if (this.statusDisabled) {
            return;
        }

        this.showStatusDropdown = !this.showStatusDropdown;
    }

    /**
     * Handle status change
     */
    async handleStatusChange(event) {
        event.preventDefault();
        event.stopPropagation();

        const newStatus = event.currentTarget.dataset.status;

        // Don't update if same status
        if (newStatus === this.workItem.status) {
            this.showStatusDropdown = false;
            return;
        }

        try {
            const fields = {};
            fields[ID_FIELD.fieldApiName] = this.workItem.id;
            fields[STATUS_FIELD.fieldApiName] = newStatus;

            const recordInput = { fields };
            await updateRecord(recordInput);

            // Hide dropdown
            this.showStatusDropdown = false;

            // Show success toast
            this.showSuccess('Status updated successfully');

            // Dispatch update event to parent (with suppressToast to avoid duplicate)
            const updateEvent = new CustomEvent('workitemupdate', {
                detail: {
                    workItemId: this.workItem.id,
                    changes: { status: newStatus },
                    suppressToast: true
                },
                bubbles: true,
                composed: true
            });
            this.dispatchEvent(updateEvent);
        } catch (error) {
            console.error('Error updating status:', error);
            this.showError(error.body?.message || 'Error updating status');
        }
    }

    // === Computed Properties ===

    /**
     * CSS class for card container (includes indentation based on level and dynamic highlights)
     */
    get cardContainerClass() {
        const baseClass = `${this.rowClass} slds-card work-item-card`;
        const levelClass = `level-${this.level}`;

        // Build highlight classes dynamically from highlights array
        const highlightClasses = this.workItem.highlights ? this.workItem.highlights.map((h) => `highlight-${h}`).join(' ') : '';

        return `${baseClass} ${levelClass} ${highlightClasses}`.trim();
    }

    /**
     * Card container style with border matching template header color
     */
    get cardContainerStyle() {
        if (this.workItem.headerColor) {
            return `border: 5px solid ${this.workItem.headerColor};`;
        }
        return '';
    }

    /**
     * Primary highlight type (for determining border color priority)
     * Priority: blocked (red) > at-risk (yellow) > timeline-conflict (orange)
     */
    get primaryHighlight() {
        if (!this.workItem.highlights || this.workItem.highlights.length === 0) {
            return null;
        }

        // Return highest priority highlight
        if (this.workItem.highlights.includes('blocked')) {
            return 'blocked';
        }
        if (this.workItem.highlights.includes('at-risk')) {
            return 'at-risk';
        }
        if (this.workItem.highlights.includes('timeline-conflict')) {
            return 'timeline-conflict';
        }

        // Default to first highlight if no priority match
        return this.workItem.highlights[0];
    }

    /**
     * CSS class for status badge
     */
    get statusBadgeClass() {
        const baseClass = 'slds-badge';
        const variantClass = 'status-' + this.workItem.workflow?.find((status) => status.name === this.workItem.status)?.variant || '';

        return `${baseClass} ${variantClass}`.trim();
    }

    /**
     * CSS class for due date (highlight if overdue)
     */
    get dueDateClass() {
        const baseClass = 'slds-text-body_regular';
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        // Parse date string as local date to avoid timezone shifts
        const [year, month, day] = this.workItem.dueDate.split('-');
        const dueDate = new Date(year, month - 1, day);

        if (dueDate < today && this.workItem.status !== 'Complete') {
            return `${baseClass} slds-text-color_error`;
        }

        return baseClass;
    }

    /**
     * Formatted start date
     */
    get formattedStartDate() {
        if (!this.workItem.startDate) {
            return '-';
        }
        // Parse date string as local date to avoid timezone shifts
        const [year, month, day] = this.workItem.startDate.split('-');
        const date = new Date(year, month - 1, day);
        return date.toLocaleDateString();
    }

    /**
     * Formatted due date
     */
    get formattedDueDate() {
        if (!this.workItem.dueDate) {
            return '-';
        }
        // Parse date string as local date to avoid timezone shifts
        const [year, month, day] = this.workItem.dueDate.split('-');
        const date = new Date(year, month - 1, day);
        return date.toLocaleDateString();
    }

    /**
     * Work Item record page URL
     */
    get workItemUrl() {
        return `/${this.workItem.id}`;
    }

    /**
     * Whether this work item has children
     */
    get hasChildren() {
        return this.workItem.children && this.workItem.children.length > 0;
    }

    /**
     * Child count
     */
    get childCount() {
        return this.hasChildren ? this.workItem.children.length : 0;
    }

    /**
     * Child level for recursive rendering
     */
    get childLevel() {
        return this.level + 1;
    }

    /**
     * Icon name for expand/collapse button
     */
    get expandIconName() {
        return this.isExpanded ? 'utility:chevrondown' : 'utility:chevronright';
    }

    /**
     * Alt text for expand/collapse icon
     */
    get expandIconAltText() {
        return this.isExpanded ? 'Collapse' : 'Expand';
    }

    /**
     * Whether to show card body (collapsed/expanded based on isExpanded state)
     */
    get showCardBody() {
        return this.isExpanded;
    }

    /**
     * Whether this work item has available child work item types
     */
    get hasAvailableChildTypes() {
        return this.allowedChildTypeCount > 0;
    }

    /**
     * Variant for Add Work Item button (neutral in compact view to match other buttons)
     */
    get addButtonVariant() {
        return this.isCompactView ? 'border-filled' : 'brand';
    }

    /**
     * Formatted hours progress percentage (limited to 1 decimal place)
     */
    get formattedHoursProgress() {
        if (!this.workItem.progress) {
            return '0.0';
        }
        return parseFloat(this.workItem.progress).toFixed(1);
    }

    /**
     * Progress bar style (width based on progress percentage)
     */
    get progressBarStyle() {
        return `width: ${this.workItem.progress}%`;
    }

    /**
     * Calculate timeline progress based on start and due dates
     */
    get timelineProgress() {
        if (!this.workItem.startDate || !this.workItem.dueDate) {
            return 0;
        }

        const today = new Date();
        today.setHours(0, 0, 0, 0); // Reset to midnight for comparison

        // Parse dates as local dates to avoid timezone shifts
        const [startYear, startMonth, startDay] = this.workItem.startDate.split('-');
        const start = new Date(startYear, startMonth - 1, startDay);

        const [dueYear, dueMonth, dueDay] = this.workItem.dueDate.split('-');
        const due = new Date(dueYear, dueMonth - 1, dueDay);

        // If hasn't started yet, 0%
        if (today < start) {
            return 0;
        }

        // If past due date, 100%
        if (today > due) {
            return 100;
        }

        // Calculate percentage of time elapsed
        const totalDuration = due.getTime() - start.getTime();
        const elapsed = today.getTime() - start.getTime();
        const progress = Math.round((elapsed / totalDuration) * 100);

        return Math.min(Math.max(progress, 0), 100); // Clamp between 0-100
    }

    /**
     * Timeline progress bar style
     */
    get timelineProgressStyle() {
        return `width: ${this.timelineProgress}%`;
    }

    /**
     * Whether to show hours progress bar (always show hours)
     */
    get showHoursProgress() {
        return true;
    }

    /**
     * Display actual hours (0 if null or undefined)
     */
    get displayActualHours() {
        return this.workItem.actualHours || 0;
    }

    /**
     * Display estimated hours (0 if null or undefined)
     */
    get displayEstimatedHours() {
        return this.workItem.estimatedHours || 0;
    }

    /**
     * Owner display name (or "Unassigned" if no owner)
     */
    get ownerDisplayName() {
        return this.workItem.ownerName || 'Unassigned';
    }

    /**
     * Resource tooltip showing list of assignments with names and roles
     */
    get resourceTooltip() {
        if (!this.workItem.assignments || this.workItem.assignments.length === 0) {
            return 'No resources assigned';
        }

        const lines = this.workItem.assignments.map((assignment) => {
            const name = assignment.resourceName || 'Unknown';
            const role = assignment.role || 'No Role';
            const primary = assignment.isPrimary ? ' (Primary)' : '';
            return `${name} - ${role}${primary}`;
        });

        return lines.join('\n');
    }

    /**
     * Resource count for display
     */
    get resourceCount() {
        return this.workItem.assignments ? this.workItem.assignments.length : 0;
    }

    /**
     * Status options for dropdown
     */
    get statusOptions() {
        let workflow = this.workItem.workflow;

        if (!workflow || !workflow.some((status) => status.name === this.workItem.status)) {
            workflow = this.defaultWorkflow;
        }

        // If no transitions defined, return all statuses
        if (!this.workItem.hasTransitions) {
            return workflow.map((status) => ({ label: status.name, value: status.name }));
        }

        // Find current status and return its transitions
        const currentStatus = workflow.find((status) => status.name === this.workItem.status);

        return currentStatus?.transitions?.map((status) => ({ label: status, value: status })) || [];
    }

    /**
     * Whether status change is disabled (no available options)
     */
    get statusDisabled() {
        return this.statusOptions.length === 0;
    }

    /**
     * Formatted resource and owner display parts for HTML rendering
     */
    get ownerAndResourcesParts() {
        const parts = [{ label: 'Owner', name: this.ownerDisplayName }];

        if (this.workItem.assignments && this.workItem.assignments.length > 0) {
            this.workItem.assignments.forEach((assignment) => {
                const name = assignment.resourceName || 'Unknown';
                const role = assignment.projectRoleName || 'No Role';
                parts.push({ label: role, name: name });
            });
        }

        return parts;
    }

    /**
     * At-risk message to display
     */
    get atRiskMessage() {
        return this.workItem.atRiskDetails || 'This work item requires attention';
    }

    /**
     * Blocked message to display
     */
    get blockedMessage() {
        return this.workItem.blockedDetails || 'This work item is blocked';
    }

    /**
     * At Risk button class (includes active state styling)
     */
    get atRiskButtonClass() {
        return this.workItem.isAtRisk ? 'at-risk-button active' : 'at-risk-button';
    }

    /**
     * Blocked button class (includes active state styling)
     */
    get blockedButtonClass() {
        return this.workItem.isBlocked ? 'blocked-button active' : 'blocked-button';
    }

    /**
     * At Risk button variant (always border-filled for consistent look)
     */
    get atRiskButtonVariant() {
        return 'border-filled';
    }

    /**
     * Blocked button variant (always border-filled for consistent look)
     */
    get blockedButtonVariant() {
        return 'border-filled';
    }

    /**
     * Delete button label
     */
    get deleteButtonLabel() {
        return this.isDeleting ? 'Deleting...' : 'Delete';
    }

    /**
     * Header style with custom color from template
     */
    get headerStyle() {
        if (this.workItem.headerColor) {
            return `background: ${this.workItem.headerColor} !important;`;
        }
        return '';
    }

    /**
     * Timeline conflict message
     */
    get timelineConflictMessage() {
        return this.workItem.timelineConflictMessage || "This work item's timeline is outside the parent work item's date range";
    }

    /**
     * Open At Risk modal
     */
    handleOpenAtRiskModal(event) {
        event.preventDefault();
        event.stopPropagation();

        this.atRiskChecked = this.workItem.isAtRisk || false;
        this.atRiskDetailsValue = this.workItem.atRiskDetails || '';
        this.showAtRiskModal = true;
    }

    /**
     * Close At Risk modal
     */
    handleCloseAtRiskModal() {
        this.showAtRiskModal = false;
    }

    /**
     * Handle At Risk checkbox change
     */
    handleAtRiskCheckboxChange(event) {
        this.atRiskChecked = event.target.checked;
    }

    /**
     * Handle At Risk details change
     */
    handleAtRiskDetailsChange(event) {
        this.atRiskDetailsValue = event.target.value;
    }

    /**
     * Save At Risk status
     */
    async handleSaveAtRisk() {
        const fields = {};
        fields[ID_FIELD.fieldApiName] = this.workItem.id;
        fields[AT_RISK_FIELD.fieldApiName] = this.atRiskChecked;
        fields[AT_RISK_DETAILS_FIELD.fieldApiName] = this.atRiskDetailsValue;

        const recordInput = { fields };

        try {
            await updateRecord(recordInput);
            this.showSuccess('At Risk status updated');

            this.showAtRiskModal = false;

            // Publish refresh event
            this.notify('workItemUpdated', { workItemId: this.workItem.id });
        } catch (error) {
            this.showError(error.body?.message || 'Error updating status');
        }
    }

    /**
     * Open Blocked modal
     */
    handleOpenBlockedModal(event) {
        event.preventDefault();
        event.stopPropagation();

        this.blockedChecked = this.workItem.isBlocked || false;
        this.blockedDetailsValue = this.workItem.blockedDetails || '';
        this.blockerWorkItemId = this.workItem.blockerWorkItemId || null;
        this.showBlockedModal = true;
    }

    /**
     * Close Blocked modal
     */
    handleCloseBlockedModal() {
        this.showBlockedModal = false;
    }

    /**
     * Handle Blocked checkbox change
     */
    handleBlockedCheckboxChange(event) {
        this.blockedChecked = event.target.checked;
    }

    /**
     * Handle Blocked details change
     */
    handleBlockedDetailsChange(event) {
        this.blockedDetailsValue = event.target.value;
    }

    /**
     * Handle blocker work item selection change
     */
    handleBlockerWorkItemChange(event) {
        this.blockerWorkItemId = event.detail.value;
    }

    /**
     * Save Blocked status
     */
    async handleSaveBlocked() {
        const fields = {};
        fields[ID_FIELD.fieldApiName] = this.workItem.id;
        fields[BLOCKED_FIELD.fieldApiName] = this.blockedChecked;
        fields[BLOCKED_DETAILS_FIELD.fieldApiName] = this.blockedDetailsValue;
        fields[BLOCKER_WORK_ITEM_FIELD.fieldApiName] = this.blockerWorkItemId;

        const recordInput = { fields };

        try {
            await updateRecord(recordInput);
            this.showSuccess('Blocked status updated');
            this.showBlockedModal = false;

            // Publish refresh event
            this.notify('workItemUpdated', { workItemId: this.workItem.id });
        } catch (error) {
            this.showError(error.body?.message || 'Error updating status');
        }
    }

    /**
     * Handle opening delete confirmation modal
     */
    handleOpenDeleteModal(event) {
        event.preventDefault();
        event.stopPropagation();
        this.showDeleteModal = true;
    }

    /**
     * Close delete modal
     */
    handleCloseDeleteModal() {
        this.showDeleteModal = false;
    }

    /**
     * Confirm and delete work item
     */
    async handleConfirmDelete() {
        this.isDeleting = true;

        try {
            await deleteRecord(this.workItem.id);

            this.showSuccess('Work Item deleted successfully');

            this.showDeleteModal = false;

            // Publish refresh event to refresh the entire project view
            this.notify('workItemDeleted', { workItemId: this.workItem.id });

            // Dispatch delete event to parent
            const deleteEvent = new CustomEvent('workitemdeleted', {
                detail: {
                    workItemId: this.workItem.id
                },
                bubbles: true,
                composed: true
            });
            this.dispatchEvent(deleteEvent);
        } catch (error) {
            console.error('Error deleting work item:', error);
            this.showError(error.body?.message || error.message || 'Unknown error');
        } finally {
            this.isDeleting = false;
        }
    }

    /**
     * Get available work items for blocker picklist
     */
    get blockerWorkItemOptions() {
        if (!this.workItemOptions || this.workItemOptions.length === 0) {
            return [];
        }

        // Filter out current work item
        return this.workItemOptions.filter((option) => option.value !== this.workItem.id);
    }

    /**
     * Whether component is in compact view mode
     */
    get isCompactView() {
        return this.viewMode === 'compact';
    }

    /**
     * Whether to show description and next steps section (hidden in compact view unless editing)
     */
    get showDescriptionSection() {
        return !this.isCompactView || this.isEditMode;
    }

    /* Drag and Drop Functionality */

    get dragData() {
        return {
            workItemId: this.workItem?.id,
            parentWorkItemId: this.workItem?.parentWorkItemId || null,
            depth: this.workItem?.depth || 0
        };
    }

    // 2. Define Rules: When can I accept a drop?
    canDrop(sourceData) {
        // todo: drop only if Parent allowr subitems of this type
        // Cannot drop on itself
        return this.workItem?.id !== sourceData.workItemId;
    }

    // 3. Define Action: What happens on success?
    onDropSuccess(sourceData) {
        this.dispatchEvent(
            new CustomEvent('reorder', {
                detail: {
                    draggedItemId: sourceData.workItemId,
                    targetItemId: this.workItem.id
                },
                bubbles: true,
                composed: true
            })
        );
    }

    get rowClass() {
        const classes = [this.dragClasses];
        if (this.workItem && this.workItem.depth > 0) {
            classes.push('child-row');
        }
        return classes.join(' ');
    }
}

