import { api, wire, track } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';
import moveWorkItem from '@salesforce/apex/WorkItemController.moveWorkItem';
import BaseComponent from 'c/baseComponent';

export default class WorkItemGantt extends BaseComponent {
    @api recordId;
    @api objectApiName;
    @api hierarchyDepth = 3;

    @track workItems = [];
    @track expandedStates = {};
    @track statusFilter = 'All';
    @track timelineBounds = null;
    @track timelineScale = null; // Will be set based on context: 'day' for Work Item, 'week' for Project
    @track parentStartDate = null;
    @track parentDueDate = null;
    @track isExpanded = true; // Controls timeline collapse/expand state - default expanded

    isLoading = false;
    error = null;
    wiredWorkItemsResult;
    scaleInitialized = false;
    parentWorkItemData = null;

    statusOptions = this.defaultStatusOptions;

    // Context detection
    get isProjectPage() {
        return this.objectApiName === 'cgpm__Project__c';
    }

    get isWorkItemPage() {
        return this.objectApiName === 'cgpm__Work_Item__c';
    }

    get effectiveProjectId() {
        return this.isProjectPage ? this.recordId : this.projectId;
    }

    get timedWorkItems() {
        if (!this.workItems) {
            return [];
        }

        return this.workItems.filter((item) => item.startDate || item.dueDate);
    }

    // Wire methods for different contexts
    @wire(getWorkItemsForProject, { projectId: '$effectiveProjectId', maxDepth: '$hierarchyDepth' })
    wiredWorkItemsForProject(result) {
        if (this.isProjectPage) {
            this.wiredWorkItemsResult = result;
            this.handleWiredData(result);
        }
    }

    @wire(getWorkItemWithChildren, { workItemId: '$recordId', maxDepth: '$hierarchyDepth' })
    wiredWorkItemWithChildren(result) {
        if (this.isWorkItemPage) {
            this.wiredWorkItemsResult = result;
            this.handleWiredData(result, true);
        }
    }

    handleWiredData(result, isWorkItemContext = false) {
        this.isLoading = true;
        const { data, error } = result;

        if (data) {
            try {
                // Initialize scale based on context (only once)
                if (!this.scaleInitialized) {
                    this.timelineScale = isWorkItemContext ? 'day' : 'week';
                    this.scaleInitialized = true;
                }

                let items = [];
                if (isWorkItemContext) {
                    // For work item page, data is single item with children
                    items = data.children || [];
                    this.projectId = data.projectId;
                    this.parentWorkItemData = data;
                    // Set parent dates from the work item (convert to YYYY-MM-DD string if Date object)
                    this.parentStartDate = this.formatDateString(data.startDate);
                    this.parentDueDate = this.formatDateString(data.dueDate);
                } else {
                    // For project page, data is ProjectDataWrapper
                    items = data.workItems || [];
                    this.statusOptions = data.statusOptions || this.statusOptions;
                    this.parentWorkItemData = null;
                    // Set parent dates from the project (convert to YYYY-MM-DD string if Date object)
                    this.parentStartDate = this.formatDateString(data.projectStartDate);
                    this.parentDueDate = this.formatDateString(data.projectDueDate);
                }

                // Process hierarchy and calculate timeline bounds
                this.workItems = this.processHierarchy(items);
                this.timelineBounds = this.calculateTimelineBounds(this.workItems);
                this.error = null;
            } catch (e) {
                this.error = e.message;
                this.showError(e.message, 'Error processing work items');
            } finally {
                this.isLoading = false;
            }
        } else if (error) {
            this.error = error;
            this.isLoading = false;
            this.showError(error.body?.message || 'Unknown error', 'Error loading work items');
        }
    }

    processHierarchy(items, depth = 0) {
        if (!items || !Array.isArray(items)) {
            return [];
        }

        return items.map((item) => {
            const processed = {
                ...item,
                depth,
                isExpanded: this.expandedStates[item.id] !== undefined ? this.expandedStates[item.id] : true, // Default to expanded for all levels
                hasChildren: item.children && Array.isArray(item.children) && item.children.length > 0
            };

            if (processed.hasChildren) {
                processed.children = this.processHierarchy(item.children, depth + 1);
            }

            return processed;
        });
    }

    calculateTimelineBounds(items) {
        if (!items || !Array.isArray(items) || items.length === 0) {
            return null;
        }

        let minDate = null;
        let maxDate = null;

        const processItem = (item) => {
            if (!item) {
                return;
            }
            if (item.startDate) {
                const start = new Date(item.startDate);
                if (!minDate || start < minDate) {
                    minDate = start;
                }
            }

            if (item.dueDate) {
                const due = new Date(item.dueDate);
                if (!maxDate || due > maxDate) {
                    maxDate = due;
                }
            }

            if (item.children && item.children.length > 0) {
                item.children.forEach(processItem);
            }
        };

        items.forEach(processItem);

        // Add buffer days
        if (minDate && maxDate) {
            minDate.setDate(minDate.getDate() - 7);
            maxDate.setDate(maxDate.getDate() + 7);
        }

        return {
            minDate: minDate ? minDate.toISOString().split('T')[0] : null,
            maxDate: maxDate ? maxDate.toISOString().split('T')[0] : null,
            today: new Date().toISOString().split('T')[0],
            scale: this.timelineScale
        };
    }

    formatDateString(dateValue) {
        if (!dateValue) {
            return null;
        }

        // If it's already a string in YYYY-MM-DD format, return as-is
        if (typeof dateValue === 'string') {
            return dateValue;
        }

        // If it's a Date object, convert to YYYY-MM-DD
        if (dateValue instanceof Date) {
            return dateValue.toISOString().split('T')[0];
        }

        return null;
    }

    handleMessage(message) {
        super.handleMessage(message);

        // Refresh for created/deleted items
        if (message.action === 'workItemCreated' || message.action === 'workItemDeleted') {
            this.handleRefresh();
            return;
        }

        // Refresh action - always refresh
        if (message.action === 'refresh') {
            this.handleRefresh();
            return;
        }

        // For updates, only refresh if the change came from outside the GANTT
        // (e.g., from Work Item List or record page edits)
        // If source='gantt', skip refresh - temp properties handle visual feedback
        if (message.action === 'workItemUpdated' && message.source !== 'gantt') {
            this.handleRefresh();
        }
    }

    // Stop event propagation for controls in header
    handleStopPropagation(event) {
        event.stopPropagation();
    }

    // Collapse/Expand Timeline
    async handleToggleCollapse() {
        this.isExpanded = !this.isExpanded;

        if (this.isExpanded) {
            // Re-subscribing to message channel when expanding
            this.subscribeToMessageChannel();
            // Auto-refresh data on expand
            await this.handleRefresh();
        } else {
            // Unsubscribe when collapsing to stop listening to events
            this.unsubscribeFromMessageChannel();
        }
    }

    // Toolbar actions
    handleExpandAll() {
        this.updateAllExpandedStates(this.workItems, true);
        this.reprocessHierarchy();
    }

    handleCollapseAll() {
        this.updateAllExpandedStates(this.workItems, false);
        this.reprocessHierarchy();
    }

    updateAllExpandedStates(items, isExpanded) {
        if (!items || !Array.isArray(items)) {
            return;
        }

        items.forEach((item) => {
            if (item && item.id) {
                this.expandedStates[item.id] = isExpanded;
                if (item.children && Array.isArray(item.children) && item.children.length > 0) {
                    this.updateAllExpandedStates(item.children, isExpanded);
                }
            }
        });
    }

    reprocessHierarchy() {
        // Re-process hierarchy to update isExpanded states on all items
        if (this.wiredWorkItemsResult && this.wiredWorkItemsResult.data) {
            let rawData;
            if (this.isWorkItemPage) {
                // For work item page, data is single item with children
                rawData = this.wiredWorkItemsResult.data.children || [];
            } else {
                // For project page, data is ProjectDataWrapper with workItems array
                rawData = this.wiredWorkItemsResult.data.workItems || [];
            }
            this.workItems = this.processHierarchy(rawData);
        }
    }

    handleStatusFilterChange(event) {
        this.statusFilter = event.detail.value;
    }

    handleScaleChange(event) {
        const scale = event.target.dataset.scale;
        if (scale && scale !== this.timelineScale) {
            this.timelineScale = scale;
            // Force timeline to rebuild with new scale
            this.timelineBounds = { ...this.timelineBounds, scale: this.timelineScale };
        }
    }

    async handleRefresh() {
        this.isLoading = true;
        try {
            await refreshApex(this.wiredWorkItemsResult);
        } catch (error) {
            this.showError(error.body?.message || 'Unknown error', 'Error refreshing data');
        } finally {
            this.isLoading = false;
        }
    }

    // Row event handlers
    handleToggleExpand(event) {
        const workItemId = event.detail.workItemId;
        this.expandedStates[workItemId] = !this.expandedStates[workItemId];

        // Re-process hierarchy to update isExpanded states
        if (this.wiredWorkItemsResult && this.wiredWorkItemsResult.data) {
            let rawData;
            if (this.isWorkItemPage) {
                // For work item page, data is single item with children
                rawData = this.wiredWorkItemsResult.data.children || [];
            } else {
                // For project page, data is ProjectDataWrapper with workItems array
                rawData = this.wiredWorkItemsResult.data.workItems || [];
            }
            this.workItems = this.processHierarchy(rawData);
        }
    }

    async handleReorder(event) {
        const { draggedItemId, targetItemId, parentWorkItemId } = event.detail;

        try {
            this.isLoading = true;

            // Call Apex to reorder
            await moveWorkItem({
                draggedItemId,
                targetItemId,
                parentWorkItemId
            });

            // Refresh the data
            await refreshApex(this.wiredWorkItemsResult);

            this.showSuccess('Work items reordered successfully');
        } catch (error) {
            this.showError(error.body?.message || error.message || 'Unknown error', 'Error reordering work items');
        } finally {
            this.isLoading = false;
        }
    }

    // Computed properties
    get hasData() {
        return this.workItems && this.workItems.length > 0;
    }

    get showTimeline() {
        return this.hasData && this.timelineBounds && this.timelineBounds.minDate && this.timelineBounds.maxDate;
    }

    get dayButtonVariant() {
        return (this.timelineScale || 'week') === 'day' ? 'brand' : 'neutral';
    }

    get weekButtonVariant() {
        return (this.timelineScale || 'week') === 'week' ? 'brand' : 'neutral';
    }

    get monthButtonVariant() {
        return (this.timelineScale || 'week') === 'month' ? 'brand' : 'neutral';
    }
}

