    99→        @AuraEnabled
   100→        public Id parentWorkItemId { get; set; }
   101→        @AuraEnabled
   102→        public Id templateId { get; set; }
   103→        @AuraEnabled
   104→        public String templateName { get; set; }
   105→        @AuraEnabled
   106→        public Integer depth { get; set; }
   107→        @AuraEnabled
   108→        public Decimal progress { get; set; }
   109→        @AuraEnabled
   110→        public Boolean isAtRisk { get; set; }
   111→        @AuraEnabled
   112→        public String atRiskDetails { get; set; }
   113→        @AuraEnabled
   114→        public Boolean isBlocked { get; set; }
   115→        @AuraEnabled
   116→        public String blockedDetails { get; set; }
