   141→        @AuraEnabled
   142→        public Date parentDueDate { get; set; }
   143→        @AuraEnabled
   144→        public List<String> highlights { get; set; }
   145→        @AuraEnabled
   146→        public String headerColor { get; set; }
   147→        @AuraEnabled
