   151→
   152→        /**
   153→         * @description Constructor from Work_Item__c record
   154→         */
   155→        public WorkItemWrapper(Work_Item__c workItem, Integer currentDepth) {
   156→            this.id = workItem.Id;
   157→            this.name = workItem.Work_Item_Name__c;
   158→            this.status = workItem.Status__c;
   159→            this.startDate = workItem.Start_Date__c;
   160→            this.dueDate = workItem.Due_Date__c;
   161→            this.estimatedHours = workItem.Estimated_Hours__c;
   162→            this.actualHours = workItem.Actual_Hours__c;
   163→            this.description = workItem.Summary__c;
   164→            this.nextSteps = workItem.Next_Steps__c;
   165→            this.projectId = workItem.Project__c;
   166→            this.parentWorkItemId = workItem.Parent_Work_Item__c;
   167→            this.templateId = workItem.Work_Item_Template__c;
   168→            this.templateName = workItem.Work_Item_Template__r?.Name;
   169→            this.depth = currentDepth;
   170→            this.progress = WorkItemService.calculateProgress(workItem.Estimated_Hours__c, workItem.Actual_Hours__c);
   171→            this.isAtRisk = workItem.At_Risk__c != null ? workItem.At_Risk__c : false;
   172→            this.atRiskDetails = workItem.At_Risk_Details__c;
   173→            this.isBlocked = workItem.Blocked__c != null ? workItem.Blocked__c : false;
   174→            this.blockedDetails = workItem.Blocked_Details__c;
   175→            this.blockerWorkItemId = workItem.Blocker_Work_Item__c;
   176→            this.blockerWorkItemName = workItem.Blocker_Work_Item__r?.Work_Item_Name__c;
   177→            this.children = new List<WorkItemWrapper>();
   178→            this.createdDate = workItem.CreatedDate;
   179→            this.lastModifiedDate = workItem.LastModifiedDate;
   180→            this.ownerId = workItem.OwnerId;
   181→            this.ownerName = workItem.Owner.Name;
   182→
   183→            // Header Color from template
   184→            this.headerColor = workItem.Work_Item_Template__r?.Header_Color__c;
   185→
   186→            // Timeline Validation logic
   187→            this.timelineValidation = workItem.Work_Item_Template__r?.Timeline_Validation__c;
   188→            this.hasTimelineConflict = false;
   189→            this.timelineConflictMessage = null;
   190→
   191→            // Workflow from template
   192→            if (workItem.Work_Item_Template__r?.Workflow__c != null) {
   193→                this.workflow = (List<StatusOption>) JSON.deserializeStrict(workItem.Work_Item_Template__r.Workflow__c, List<StatusOption>.class);
   194→
   195→                this.hasTransitions = false;
   196→                for (StatusOption option : this.workflow) {
   197→                    if (option.transitions != null && !option.transitions.isEmpty()) {
   198→                        this.hasTransitions = true;
   199→                        break;
   200→                    }
   201→                }
   202→            }
   203→
   204→            // Check if this work item has a parent and timeline validation is enabled
   205→            if (workItem.Parent_Work_Item__c != null && this.timelineValidation == 'Warning' && workItem.Start_Date__c != null && workItem.Due_Date__c != null) {
   206→                this.parentStartDate = workItem.Parent_Work_Item__r?.Start_Date__c;
   207→                this.parentDueDate = workItem.Parent_Work_Item__r?.Due_Date__c;
   208→
   209→                // Check if child dates are outside parent range
   210→                if (this.parentStartDate != null && this.parentDueDate != null) {
   211→                    if (workItem.Start_Date__c < this.parentStartDate || workItem.Due_Date__c > this.parentDueDate) {
   212→                        this.hasTimelineConflict = true;
   213→                        this.timelineConflictMessage =
   214→                            'This work item\'s timeline extends outside the parent work item\'s date range (' +
   215→                            this.parentStartDate.format() +
   216→                            ' - ' +
   217→                            this.parentDueDate.format() +
   218→                            ')';
   219→                    }
   220→                }
   221→            }
   222→
   223→            // Build highlights array based on various alert conditions
   224→            this.highlights = new List<String>();
   225→            if (this.isAtRisk) {
   226→                this.highlights.add('at-risk');
   227→            }
   228→            if (this.isBlocked) {
   229→                this.highlights.add('blocked');
   230→            }
   231→            if (this.hasTimelineConflict) {
   232→                this.highlights.add('timeline-conflict');
   233→            }
   234→
   235→            this.assignments = new List<WorkItemAssignmentWrapper>();
   236→
   237→            // Populate assignments from Work Item Assignments
   238→            if (workItem.Work_Item_Assignments__r != null) {
   239→                for (Work_Item_Assignment__c assignment : workItem.Work_Item_Assignments__r) {
   240→                    WorkItemAssignmentWrapper assignmentWrapper = new WorkItemAssignmentWrapper();
   241→                    assignmentWrapper.id = assignment.Id;
   242→                    assignmentWrapper.role = assignment.Role_on_Work_Item__c;
   243→                    assignmentWrapper.isPrimary = assignment.Is_Primary__c;
   244→                    assignmentWrapper.projectRoleId = assignment.Project_Role__c;
   245→                    assignmentWrapper.projectRoleName = assignment.Project_Role__r?.Name;
   246→
   247→                    // Get resource name from either User or Contact
   248→                    if (assignment.Resource_Assignment__r?.Resource_User__c != null) {
   249→                        assignmentWrapper.resourceName = assignment.Resource_Assignment__r.Resource_User__r?.Name;
   250→                    } else if (assignment.Resource_Assignment__r?.Resource_Contact__c != null) {
   251→                        assignmentWrapper.resourceName = assignment.Resource_Assignment__r.Resource_Contact__r?.Name;
   252→                    }
   253→
   254→                    this.assignments.add(assignmentWrapper);
   255→                }
   256→            }
   257→        }
   258→    }
