   670→    /**
   671→     * @description Reorder work items by updating Order__c values and handling re-parenting
   672→     * @param draggedItemId The ID of the work item being dragged
   673→     * @param targetItemId The ID of the work item being dropped on
   674→     * @param draggedParentId The parent ID of the dragged work item (null for root items)
   675→     * @param targetParentId The parent ID of the target work item (null for root items). When equal to targetItemId, makes dragged item a child of target.
   676→     */
   677→    @AuraEnabled
   678→    public static void moveWorkItem(Id draggedItemId, Id targetItemId) {
   679→        if (draggedItemId == null || targetItemId == null) {
   680→            throw new AppException('Dragged and target work item IDs are required');
   681→        }
   682→
   683→        if (draggedItemId == targetItemId) {
   684→            return; // No reorder needed
   685→        }
   686→
   687→        try {
   688→            // First, get the project ID from the dragged item
   689→            Map<Id, Work_Item__c> itemsByIds = new Map<Id, Work_Item__c>(
   690→                [
   691→                    SELECT Id, Project__c, Parent_Work_Item__c, Work_Item_Template__c
   692→                    FROM Work_Item__c
   693→                    WHERE Id IN :new Set<Id>{ draggedItemId, targetItemId }
   694→                    WITH USER_MODE
   695→                ]
   696→            );
   697→
   698→            Work_Item__c draggedItem = itemsByIds.get(draggedItemId);
   699→            Work_Item__c targetItem = itemsByIds.get(targetItemId);
   700→
   701→            // Use targetParentId to determine if reparenting is needed
   702→            if (draggedItem.Parent_Work_Item__c == targetItem.Parent_Work_Item__c) {
   703→                // Same parent, just reorder
   704→                reorderWorkItem(draggedItem, targetItem);
   705→            } else {
   706→                // Different parent, reparent
   707→                reparentWorkItem(draggedItem, targetItem);
   708→            }
   709→        } catch (Exception e) {
   710→            System.debug(LoggingLevel.ERROR, 'Error reordering work items: ' + e.getMessage());
   711→            throw new AppException('Error reordering work items: ' + e.getMessage());
   712→        }
   713→    }
   714→
   715→    private static void reorderWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
   716→        // Query all siblings (items with same parent)
   717→        List<Work_Item__c> siblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);
   718→
   719→        if (siblings.isEmpty()) {
   720→            throw new AppException('No work items found to reorder');
   721→        }
   722→
   723→        Integer draggedIndex = getIndex(siblings, draggedItem.Id);
   724→        Integer targetIndex = getIndex(siblings, targetItem.Id);
   725→
   726→        // Reorder the list
   727→        Work_Item__c movedItem = siblings.remove(draggedIndex);
   728→
   729→        insertItem(siblings, targetIndex, movedItem);
   730→
   731→        // Reassign Order values
   732→        orderWorkItems(siblings);
   733→    }
   734→
   735→    private static void reparentWorkItem(Work_Item__c draggedItem, Work_Item__c targetItem) {
   736→        Id newParentId = null;
   737→        Boolean asParent = false;
   738→
   739→        // Strategy 1: Assume drop was onto parent (targetItem becomes the new parent)
   740→        // Check if targetItem's template allows draggedItem's template as a child
   741→        Integer allowedAsChildCount = [
   742→            SELECT COUNT()
   743→            FROM Allowed_Child_Type__c
   744→            WHERE Parent_Work_Item_Template__c = :targetItem.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   745→            WITH USER_MODE
   746→        ];
   747→
   748→        if (allowedAsChildCount > 0) {
   749→            // Valid: targetItem can be the parent
   750→            newParentId = targetItem.Id;
   751→            asParent = true;
   752→        } else {
   753→            // Strategy 2: Try as sibling (targetItem's parent becomes the new parent)
   754→            if (targetItem.Parent_Work_Item__c != null) {
   755→                // targetItem has a parent - check if that parent allows draggedItem
   756→                Work_Item__c targetParent = [
   757→                    SELECT Id, Work_Item_Template__c
   758→                    FROM Work_Item__c
   759→                    WHERE Id = :targetItem.Parent_Work_Item__c
   760→                    WITH USER_MODE
   761→                    LIMIT 1
   762→                ];
   763→
   764→                Integer allowedAsSiblingCount = [
   765→                    SELECT COUNT()
   766→                    FROM Allowed_Child_Type__c
   767→                    WHERE Parent_Work_Item_Template__c = :targetParent.Work_Item_Template__c AND Child_Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   768→                    WITH USER_MODE
   769→                ];
   770→
   771→                if (allowedAsSiblingCount > 0) {
   772→                    // Valid: targetItem's parent can be the parent (making them siblings)
   773→                    newParentId = targetItem.Parent_Work_Item__c;
   774→                    asParent = false;
   775→                } else {
   776→                    throw new AppException('Cannot move work item: neither the target nor its parent allows this work item type as a child.');
   777→                }
   778→            } else {
   779→                // targetItem is a root item - check if project template allows draggedItem at root
   780→                Project__c project = [
   781→                    SELECT Id, Project_Template__c
   782→                    FROM Project__c
   783→                    WHERE Id = :draggedItem.Project__c
   784→                    WITH USER_MODE
   785→                    LIMIT 1
   786→                ];
   787→
   788→                Integer allowedAtRootCount = [
   789→                    SELECT COUNT()
   790→                    FROM Project_Template_Work_Item_Type__c
   791→                    WHERE Project_Template__c = :project.Project_Template__c AND Work_Item_Template__c = :draggedItem.Work_Item_Template__c
   792→                    WITH USER_MODE
   793→                ];
   794→
   795→                if (allowedAtRootCount > 0) {
   796→                    // Valid: draggedItem can be at root level (sibling to targetItem)
   797→                    newParentId = null;
   798→                    asParent = false;
   799→                } else {
   800→                    throw new AppException('Cannot move work item: target does not allow this work item type as a child, and project template does not allow it at root level.');
   801→                }
   802→            }
   803→        }
   804→
   805→        // Query all siblings (items with same parent)
   806→        List<Work_Item__c> oldSiblings = getSiblings(draggedItem.Parent_Work_Item__c ?? draggedItem.Project__c);
   807→        List<Work_Item__c> newSiblings;
   808→
   809→        if (asParent) {
   810→            // Dropping onto parent - get children of targetItem
   811→            newSiblings = getSiblings(targetItem.Id);
   812→        } else {
   813→            // Dropping as sibling - get siblings of targetItem
   814→            newSiblings = getSiblings(targetItem.Parent_Work_Item__c ?? targetItem.Project__c);
   815→        }
   816→
   817→        // Find indices
   818→        Integer draggedIndex = getIndex(oldSiblings, draggedItem.Id);
   819→        Work_Item__c movedItem = oldSiblings.remove(draggedIndex);
   820→
   821→        Integer targetIndex;
   822→
   823→        if (asParent) {
   824→            // Dropping onto parent - add to end of children
   825→            targetIndex = newSiblings.size();
   826→        } else {
   827→            // Dropping as sibling - insert at target position
   828→            targetIndex = getIndex(newSiblings, targetItem.Id);
   829→        }
   830→
   831→        movedItem.Parent_Work_Item__c = newParentId;
   832→        insertItem(newSiblings, targetIndex, movedItem);
   833→
   834→        orderWorkItems(oldSiblings);
   835→        orderWorkItems(newSiblings);
   836→    }
   837→
   838→    private static List<Work_Item__c> getSiblings(Id parentId) {
   839→        if (parentId.getSobjectType().equals(Project__c.getSObjectType())) {
   840→            return [
   841→                SELECT Id, Order__c, Parent_Work_Item__c
   842→                FROM Work_Item__c
   843→                WHERE Parent_Work_Item__c = NULL AND Project__c = :parentId
   844→                WITH USER_MODE
   845→                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
   846→            ];
   847→        } else if (parentId.getSobjectType().equals(Work_Item__c.getSObjectType())) {
   848→            return [
   849→                SELECT Id, Order__c, Parent_Work_Item__c
   850→                FROM Work_Item__c
   851→                WHERE Parent_Work_Item__c = :parentId
   852→                WITH USER_MODE
   853→                ORDER BY Order__c ASC NULLS LAST, CreatedDate ASC
   854→            ];
   855→        }
   856→
   857→        return new List<Work_Item__c>();
   858→    }
   859→
   860→    private static void insertItem(List<Work_Item__c> newSiblings, Integer targetIndex, Work_Item__c movedItem) {
   861→        if (newSiblings.size() <= targetIndex) {
   862→            newSiblings.add(movedItem);
   863→        } else {
   864→            newSiblings.add(targetIndex, movedItem);
   865→        }
   866→    }
   867→
   868→    private static Integer getIndex(List<Work_Item__c> records, Id itemId) {
   869→        Integer index = -1;
   870→        for (Integer i = 0; i < records.size(); i++) {
   871→            if (records[i].Id == itemId) {
   872→                index = i;
   873→            }
   874→        }
   875→
   876→        if (index == -1) {
   877→            List<String> foundIds = new List<String>();
   878→
   879→            for (Work_Item__c wi : records) {
   880→                foundIds.add(wi.Id);
   881→            }
   882→
   883→            throw new AppException('Could not find work item ' + itemId + ' in sibling list. Found ' + records.size() + ' siblings: ' + String.join(foundIds, ', '));
   884→        }
   885→
   886→        return index;
   887→    }
   888→
   889→    private static void orderWorkItems(List<Work_Item__c> siblings) {
   890→        List<Work_Item__c> itemsToUpdate = new List<Work_Item__c>();
   891→        Decimal orderValue = 0;
   892→
   893→        for (Work_Item__c item : siblings) {
   894→            item.Order__c = orderValue++;
   895→            itemsToUpdate.add(item);
   896→        }
   897→
   898→        // Update with FLS enforcement
   899→        SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, itemsToUpdate);
   900→
   901→        update decision.getRecords();
   902→    }
   903→
   904→    /**
   905→     * @description Update the owner (primary resource) of a work item
   906→     * @param workItemId The Work Item ID
   907→     * @param newOwnerId The new Owner User ID
   908→     */
   909→    @AuraEnabled
   910→    public static void updateWorkItemOwner(Id workItemId, Id newOwnerId) {
   911→        if (workItemId == null) {
   912→            throw new AppException('Work Item ID is required');
   913→        }
   914→
   915→        if (newOwnerId == null) {
   916→            throw new AppException('Owner ID is required');
   917→        }
   918→
   919→        try {
   920→            Work_Item__c workItem = new Work_Item__c(Id = workItemId, OwnerId = newOwnerId);
   921→
   922→            // Use stripInaccessible to enforce FLS
   923→            SObjectAccessDecision decision = Security.stripInaccessible(AccessType.UPDATABLE, new List<Work_Item__c>{ workItem });
   924→
   925→            update decision.getRecords();
   926→        } catch (Exception e) {
   927→            System.debug(LoggingLevel.ERROR, 'Error updating work item owner: ' + e.getMessage());
   928→            throw new AppException('Error updating work item owner: ' + e.getMessage());
   929→        }
   930→    }
   931→
   932→    /**
   933→     * @description Wrapper class for Time Entries
   934→     */
   935→    public class TimeEntryWrapper {
   936→        @AuraEnabled
   937→        public Id id { get; set; }
   938→        @AuraEnabled
   939→        public String timeEntryNumber { get; set; }
   940→        @AuraEnabled
   941→        public Date entryDate { get; set; }
   942→        @AuraEnabled
   943→        public Decimal hours { get; set; }
   944→        @AuraEnabled
   945→        public String description { get; set; }
   946→        @AuraEnabled
   947→        public Id workItemId { get; set; }
   948→        @AuraEnabled
   949→        public String workItemName { get; set; }
   950→        @AuraEnabled
   951→        public String resourceName { get; set; }
   952→        @AuraEnabled
   953→        public Id resourceAssignmentId { get; set; }
   954→        @AuraEnabled
   955→        public Datetime createdDate { get; set; }
   956→        @AuraEnabled
   957→        public String createdByName { get; set; }
   958→    }
   959→
   960→    /**
   961→     * @description Get time entries for a work item and all its descendants
   962→     * @param workItemId The ID of the Work Item
   963→     *
   964→     * @return List of time entry records including entries from all child work items
   965→     */
   966→    @AuraEnabled(Cacheable=false)
   967→    public static List<TimeEntryWrapper> getTimeEntriesForWorkItem(Id workItemId) {
   968→        if (workItemId == null) {
   969→            throw new AppException('Work Item ID is required');
   970→        }
   971→
   972→        try {
   973→            List<TimeEntryWrapper> wrappers = new List<TimeEntryWrapper>();
   974→
   975→            // Get all descendant work item IDs
   976→            Set<Id> allWorkItemIds = getAllDescendantWorkItemIds(workItemId);
   977→
   978→            // Query time entries for this work item and all descendants
   979→            List<Time_Entry__c> timeEntries = [
   980→                SELECT
   981→                    Id,
   982→                    Name,
   983→                    Date__c,
   984→                    Hours__c,
   985→                    Description__c,
   986→                    Work_Item__c,
   987→                    Work_Item__r.Work_Item_Name__c,
   988→                    Resource_Assignment__c,
   989→                    Resource_Assignment__r.Resource_Name__c,
   990→                    CreatedDate,
   991→                    CreatedBy.Name
   992→                FROM Time_Entry__c
   993→                WHERE Work_Item__c IN :allWorkItemIds
   994→                WITH USER_MODE
   995→                ORDER BY Date__c DESC, CreatedDate DESC
   996→                LIMIT 500
   997→            ];
   998→
   999→            for (Time_Entry__c entry : timeEntries) {
  1000→                TimeEntryWrapper wrapper = new TimeEntryWrapper();
  1001→                wrapper.id = entry.Id;
  1002→                wrapper.timeEntryNumber = entry.Name;
  1003→                wrapper.entryDate = entry.Date__c;
  1004→                wrapper.hours = entry.Hours__c;
  1005→                wrapper.description = entry.Description__c;
  1006→                wrapper.workItemId = entry.Work_Item__c;
  1007→                wrapper.workItemName = entry.Work_Item__r != null ? entry.Work_Item__r.Work_Item_Name__c : null;
  1008→                wrapper.resourceName = entry.Resource_Assignment__r != null ? entry.Resource_Assignment__r.Resource_Name__c : null;
  1009→                wrapper.resourceAssignmentId = entry.Resource_Assignment__c;
  1010→                wrapper.createdDate = entry.CreatedDate;
  1011→                wrapper.createdByName = entry.CreatedBy.Name;
  1012→                wrappers.add(wrapper);
  1013→            }
  1014→
  1015→            return wrappers;
  1016→        } catch (Exception e) {
  1017→            System.debug(LoggingLevel.ERROR, 'Error retrieving time entries: ' + e.getMessage());
  1018→            throw new AppException('Error retrieving time entries: ' + e.getMessage());
  1019→        }
  1020→    }
  1021→
  1022→    /**
  1023→     * @description Recursively get all descendant work item IDs
  1024→     * @param workItemId The root work item ID
  1025→     *
  1026→     * @return Set of all work item IDs including the root and all descendants
  1027→     */
  1028→    private static Set<Id> getAllDescendantWorkItemIds(Id workItemId) {
  1029→        Set<Id> allIds = new Set<Id>{ workItemId };
  1030→        Set<Id> currentLevelIds = new Set<Id>{ workItemId };
  1031→
  1032→        // Recursively fetch children up to a reasonable depth (prevent infinite loops)
  1033→        for (Integer i = 0; i < 10; i++) {
  1034→            Set<Id> nextLevelIds = new Set<Id>();
  1035→
  1036→            for (Work_Item__c child : [
  1037→                SELECT Id
  1038→                FROM Work_Item__c
  1039→                WHERE Parent_Work_Item__c IN :currentLevelIds
  1040→                WITH USER_MODE
  1041→            ]) {
  1042→                nextLevelIds.add(child.Id);
  1043→                allIds.add(child.Id);
  1044→            }
  1045→
  1046→            if (nextLevelIds.isEmpty()) {
  1047→                break;
  1048→            }
  1049→
  1050→            currentLevelIds = nextLevelIds;
  1051→        }
  1052→
  1053→        return allIds;
  1054→    }
  1055→
  1056→    /**
  1057→     * Recursively builds hierarchy by fetching children for parent Work Items
  1058→     *
  1059→     * @param wrappers List of parent wrappers to populate with children
  1060→     * @param parentIds Set of parent IDs to query children for
  1061→     * @param currentDepth Current depth in the hierarchy
  1062→     * @param maxDepth Maximum depth to traverse
  1063→     */
  1064→    private static void buildHierarchy(List<WorkItemWrapper> wrappers, Set<Id> parentIds, Integer currentDepth, Integer maxDepth) {
  1065→        if (currentDepth > maxDepth || parentIds.isEmpty()) {
  1066→            return;
  1067→        }
  1068→
  1069→        // Get all children for the current level
  1070→        Map<Id, List<Work_Item__c>> parentToChildrenMap = WorkItemService.getChildrenForParents(parentIds);
  1071→
  1072→        if (parentToChildrenMap.isEmpty()) {
  1073→            return;
  1074→        }
  1075→
  1076→        // Map wrappers by ID for quick lookup
  1077→        Map<Id, WorkItemWrapper> wrapperMap = new Map<Id, WorkItemWrapper>();
  1078→        for (WorkItemWrapper wrapper : wrappers) {
  1079→            wrapperMap.put(wrapper.id, wrapper);
  1080→        }
  1081→
  1082→        // Attach children to their parents
  1083→        Set<Id> nextLevelIds = new Set<Id>();
  1084→        List<WorkItemWrapper> nextLevelWrappers = new List<WorkItemWrapper>();
  1085→
  1086→        for (Id parentId : parentToChildrenMap.keySet()) {
  1087→            WorkItemWrapper parentWrapper = wrapperMap.get(parentId);
  1088→            if (parentWrapper != null) {
  1089→                for (Work_Item__c child : parentToChildrenMap.get(parentId)) {
  1090→                    WorkItemWrapper childWrapper = new WorkItemWrapper(child, currentDepth);
  1091→                    parentWrapper.children.add(childWrapper);
  1092→                    nextLevelIds.add(child.Id);
  1093→                    nextLevelWrappers.add(childWrapper);
  1094→                }
  1095→            }
  1096→        }
  1097→
  1098→        // Recursively process next level
  1099→        if (!nextLevelWrappers.isEmpty() && currentDepth < maxDepth) {
  1100→            buildHierarchy(nextLevelWrappers, nextLevelIds, currentDepth + 1, maxDepth);
  1101→        }
  1102→    }
  1103→}

