import { api, track, wire } from 'lwc';
import { refreshApex } from '@salesforce/apex';
import getAvailableResources from '@salesforce/apex/WorkItemController.getAvailableResources';
import getProjectRoles from '@salesforce/apex/WorkItemController.getProjectRoles';
import refreshWorkItem from '@salesforce/apex/WorkItemController.refreshWorkItem';
import addWorkItemAssignment from '@salesforce/apex/WorkItemController.addWorkItemAssignment';
import removeWorkItemAssignment from '@salesforce/apex/WorkItemController.removeWorkItemAssignment';
import updateWorkItemOwner from '@salesforce/apex/WorkItemController.updateWorkItemOwner';
import BaseComponent from 'c/baseComponent';

export default class ResourceAssignmentModal extends BaseComponent {
    @api workItemId;
    @api workItemName;
    @api projectId;

    @track _currentAssignments = [];
    @track _ownerId;
    @track _ownerName;
    @track _isOpen = false;
    @track isLoading = false;
    @track isEditingOwner = false;
    @track selectedResourceId;
    @track selectedProjectRoleId;
    @track selectedOwnerId;

    availableResources = [];
    projectRoles = [];
    wiredResourcesResult;
    wiredProjectRolesResult;

    // Track if modal should stay open after data refresh
    shouldStayOpen = false;

    @api
    get currentAssignments() {
        return this._currentAssignments;
    }
    set currentAssignments(value) {
        this._currentAssignments = value || [];
    }

    @api
    get ownerId() {
        return this._ownerId;
    }
    set ownerId(value) {
        this._ownerId = value;
    }

    @api
    get ownerName() {
        return this._ownerName;
    }
    set ownerName(value) {
        this._ownerName = value;
    }

    get isOpen() {
        return this._isOpen;
    }

    /**
     * Wire to get available resources for the project
     */
    @wire(getAvailableResources, { projectId: '$projectId' })
    wiredResources(result) {
        this.wiredResourcesResult = result;
        const { data, error } = result;

        if (data) {
            this.availableResources = data;
        } else if (error) {
            this.showError('Failed to load available resources');
            console.error('Error loading resources:', error);
        }
    }

    /**
     * Wire to get project roles
     */
    @wire(getProjectRoles, { projectId: '$projectId' })
    wiredProjectRoles(result) {
        this.wiredProjectRolesResult = result;
        const { data, error } = result;

        if (data) {
            this.projectRoles = data;
        } else if (error) {
            this.showError('Failed to load project roles');
            console.error('Error loading project roles:', error);
        }
    }

    /**
     * Open the modal
     */
    @api
    async open() {
        this._isOpen = true;
        this.shouldStayOpen = false;
        this.resetForm();

        // Refresh work item data when opening to ensure we have latest assignments
        await this.refreshWorkItemData();
    }

    /**
     * Close the modal
     */
    @api
    close() {
        this._isOpen = false;
        this.shouldStayOpen = false;
        this.isEditingOwner = false;
        this.resetForm();
    }

    /**
     * Handle close button click
     */
    handleClose() {
        // Trigger a final refresh of the parent component before closing
        this.dispatchEvent(
            new CustomEvent('modalclosed', {
                detail: { workItemId: this.workItemId },
                bubbles: true,
                composed: true
            })
        );

        this.close();
    }

    /**
     * Called when parent component data refreshes
     */
    renderedCallback() {
        // If modal should stay open and it got closed due to data refresh, reopen it
        if (this.shouldStayOpen && !this._isOpen) {
            this._isOpen = true;
        }
    }

    /**
     * Handle edit owner button click
     */
    handleEditOwner() {
        this.isEditingOwner = true;
        this.selectedOwnerId = this._ownerId;
    }

    /**
     * Handle cancel owner edit
     */
    handleCancelOwnerEdit() {
        this.isEditingOwner = false;
        this.selectedOwnerId = null;
    }

    /**
     * Handle owner selection change
     */
    handleOwnerChange(event) {
        this.selectedOwnerId = event.detail.value;
    }

    /**
     * Handle save owner
     */
    async handleSaveOwner() {
        if (!this.selectedOwnerId) {
            this.showWarning('Please select a new owner', 'Missing Information');
            return;
        }

        this.isLoading = true;
        this.shouldStayOpen = true; // Mark that modal should stay open

        try {
            await updateWorkItemOwner({
                workItemId: this.workItemId,
                newOwnerId: this.selectedOwnerId
            });

            this.showSuccess('Primary resource (owner) updated successfully');
            this.isEditingOwner = false;
            this.selectedOwnerId = null;

            // Refresh the work item data to update displays
            await this.refreshWorkItemData();

            // Refresh available resources
            await refreshApex(this.wiredResourcesResult);
        } catch (error) {
            this.shouldStayOpen = false; // Don't stay open on error
            this.showError(error.body?.message || 'Failed to update owner');
            console.error('Error updating owner:', error);
        } finally {
            this.isLoading = false;
        }
    }

    /**
     * Handle resource selection change
     */
    handleResourceChange(event) {
        this.selectedResourceId = event.detail.value;

        // Auto-populate project role from selected resource's default role
        if (this.selectedResourceId && this.availableResources) {
            const selectedResource = this.availableResources.find((r) => r.id === this.selectedResourceId);
            if (selectedResource && selectedResource.defaultRoleId) {
                this.selectedProjectRoleId = selectedResource.defaultRoleId;
            }
        }
    }

    /**
     * Handle project role selection change
     */
    handleProjectRoleChange(event) {
        this.selectedProjectRoleId = event.detail.value;
    }

    /**
     * Handle add assignment
     */
    async handleAddAssignment() {
        if (!this.selectedResourceId) {
            this.showWarning('Please select a resource', 'Missing Information');
            return;
        }

        this.isLoading = true;
        this.shouldStayOpen = true; // Mark that modal should stay open

        try {
            await addWorkItemAssignment({
                workItemId: this.workItemId,
                resourceAssignmentId: this.selectedResourceId,
                role: null,
                isPrimary: false,
                projectRoleId: this.selectedProjectRoleId
            });

            this.showSuccess('Resource assignment added successfully');
            this.resetForm();

            // Refresh the work item data to update displays
            await this.refreshWorkItemData();

            // Refresh available resources
            await refreshApex(this.wiredResourcesResult);
        } catch (error) {
            this.shouldStayOpen = false; // Don't stay open on error
            this.showError(error.body?.message || 'Failed to add resource assignment');
            console.error('Error adding assignment:', error);
        } finally {
            this.isLoading = false;
        }
    }

    /**
     * Handle remove assignment
     */
    async handleRemoveAssignment(event) {
        const assignmentId = event.currentTarget.dataset.assignmentId;

        if (!assignmentId) {
            return;
        }

        this.isLoading = true;
        this.shouldStayOpen = true; // Mark that modal should stay open

        try {
            await removeWorkItemAssignment({ assignmentId });

            this.showSuccess('Resource assignment removed successfully');

            // Refresh the work item data to update displays
            await this.refreshWorkItemData();

            // Refresh available resources
            await refreshApex(this.wiredResourcesResult);
        } catch (error) {
            this.shouldStayOpen = false; // Don't stay open on error
            this.showError(error.body?.message || 'Failed to remove resource assignment');
            console.error('Error removing assignment:', error);
        } finally {
            this.isLoading = false;
        }
    }

    /**
     * Refresh work item data to update modal display
     */
    async refreshWorkItemData() {
        try {
            const updatedWorkItem = await refreshWorkItem({
                workItemId: this.workItemId
            });

            // Update the modal's internal tracked properties
            this._ownerId = updatedWorkItem.ownerId;
            this._ownerName = updatedWorkItem.ownerName;
            this._currentAssignments = updatedWorkItem.assignments || [];

            // Update the parent card's data by dispatching an event
            this.dispatchEvent(
                new CustomEvent('workitemdatarefreshed', {
                    detail: { workItem: updatedWorkItem },
                    bubbles: true,
                    composed: true
                })
            );
        } catch (error) {
            console.error('Error refreshing work item data:', error);
        }
    }

    /**
     * Reset form fields
     */
    resetForm() {
        this.selectedResourceId = null;
        this.selectedProjectRoleId = null;
    }

    // === Computed Properties ===

    /**
     * Whether there are additional assignments (excluding owner)
     */
    get hasAdditionalAssignments() {
        return this._currentAssignments && this._currentAssignments.length > 0;
    }

    /**
     * Available resource options for combobox
     */
    get availableResourceOptions() {
        if (!this.availableResources || this.availableResources.length === 0) {
            return [];
        }

        return this.availableResources.map((resource) => ({
            label: resource.resourceName,
            value: resource.id
        }));
    }

    /**
     * Available user options for owner change (from resources that are Users)
     */
    get availableUserOptions() {
        if (!this.availableResources || this.availableResources.length === 0) {
            return [];
        }

        // Filter to only User-based resource assignments and map to User IDs
        return this.availableResources
            .filter((resource) => resource.userId != null)
            .map((resource) => ({
                label: resource.resourceName,
                value: resource.userId
            }));
    }

    /**
     * Project role options for combobox
     */
    get projectRoleOptions() {
        if (!this.projectRoles || this.projectRoles.length === 0) {
            return [];
        }

        return this.projectRoles.map((role) => ({
            label: role.Name,
            value: role.Id
        }));
    }

    /**
     * Whether add button should be disabled
     */
    get isAddDisabled() {
        return !this.selectedResourceId || this.isLoading;
    }

    /**
     * Whether save owner button should be disabled
     */
    get isSaveOwnerDisabled() {
        return !this.selectedOwnerId || this.selectedOwnerId === this._ownerId || this.isLoading;
    }
}

