import { api } from 'lwc';
import DraggableComponent from 'c/draggableComponent';

export default class WorkItemGanttRow extends DraggableComponent {
    @api workItem;
    @api timelineBounds;
    @api statusFilter = 'All';

    isDragging = false;
    isDropTarget = false;

    // Computed properties
    get isVisible() {
        if (!this.workItem) {
            return false;
        }
        if (this.statusFilter === 'All') {
            return true;
        }
        return this.workItem.status === this.statusFilter;
    }

    get timedChildren() {
        if (!this.workItem) {
            return [];
        }

        return this.workItem.children.filter((child) => child.startDate || child.dueDate);
    }

    get hasChildren() {
        if (!this.workItem) {
            return false;
        }

        return this.timedChildren.length > 0;
    }

    get showChildren() {
        return this.hasChildren && this.workItem && this.workItem.isExpanded;
    }

    get expandIconName() {
        return this.workItem && this.workItem.isExpanded ? 'utility:chevrondown' : 'utility:chevronright';
    }

    get indentStyle() {
        if (!this.workItem) {
            return 'padding-left: 0px;';
        }
        const indent = (this.workItem.depth || 0) * 20;
        return `padding-left: ${indent}px;`;
    }

    get rowClass() {
        const classes = [this.dragClasses];
        if (this.workItem && this.workItem.depth > 0) {
            classes.push('child-row');
        }
        return classes.join(' ');
    }

    get labelClass() {
        const classes = ['work-item-label'];
        if (this.hasChildren) {
            classes.push('has-children');
        }
        return classes.join(' ');
    }

    get statusClass() {
        if (!this.workItem) {
            return 'status-badge status-neutral';
        }
        let workflow = this.workItem.workflow?.find((status) => status.name === this.workItem.status) || this.defaultWorkflow;
        const variant = workflow?.variant || 'neutral';
        return `status-badge status-${variant}`;
    }

    get formattedHours() {
        if (!this.workItem) {
            return '-';
        }
        const estimated = this.workItem.estimatedHours || 0;
        const actual = this.workItem.actualHours || 0;
        if (estimated > 0 || actual > 0) {
            return `${actual}h / ${estimated}h`;
        }
        return '-';
    }

    get atRiskMessage() {
        return this.workItem?.atRiskDetails || 'This work item requires attention';
    }

    get blockedMessage() {
        return this.workItem?.blockedDetails || 'This work item is blocked';
    }

    // Event handlers
    handleToggleExpand() {
        if (!this.hasChildren) {
            return;
        }

        const event = new CustomEvent('toggleexpand', {
            detail: { workItemId: this.workItem.id },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(event);
    }

    handleDateUpdate(event) {
        // Bubble up to parent
        const bubbledEvent = new CustomEvent('dateupdate', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    handleRefresh(event) {
        // Bubble up to parent
        const bubbledEvent = new CustomEvent('refresh', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    handleReorder(event) {
        // Bubble up to parent
        const bubbledEvent = new CustomEvent('reorder', {
            detail: event.detail,
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(bubbledEvent);
    }

    /* Drag and Drop Functionality */

    get dragData() {
        return {
            workItemId: this.workItem?.id,
            parentWorkItemId: this.workItem?.parentWorkItemId || null,
            depth: this.workItem?.depth || 0
        };
    }

    canDrop(sourceData) {
        // Cannot drop on itself
        return this.workItem?.id !== sourceData.workItemId;
    }

    onDropSuccess(sourceData) {
        this.dispatchEvent(
            new CustomEvent('reorder', {
                detail: {
                    draggedItemId: sourceData.workItemId,
                    targetItemId: this.workItem.id
                },
                bubbles: true,
                composed: true
            })
        );
    }
}

