    18→    @track resizeEdge = null; // 'left' or 'right'
    19→    @track tempLeft = null; // Temporary position during drag
    20→    @track tempWidth = null; // Temporary width during resize
    21→    @track tempStartDate = null; // Temporary start date during drag/resize
    22→    @track tempDueDate = null; // Temporary due date during drag/resize
