    28→
    29→    get columnWidthInPixels() {
    30→        // Column width in pixels based on scale
    31→        if (this.scale === 'day') {
    32→            return 80;
    33→        }
    34→        if (this.scale === 'week') {
    35→            return 160;
    36→        }
    37→        if (this.scale === 'month') {
    38→            return 360;
    39→        }
    40→        return 160;
    41→    }
    42→
    43→    get columnWidthInDays() {
    44→        // How many days each column represents
    45→        if (this.scale === 'day') {
    46→            return 1;
    47→        }
    48→        if (this.scale === 'week') {
    49→            return 7;
    50→        }
    51→        if (this.scale === 'month') {
    52→            return 30;
