   404→            // Adjust due date (keeps local time)
   405→            newStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate());
   406→            newDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);
   407→
   408→            // Ensure due is after start
