   412→            }
   413→        }
   414→
   415→        await this.updateWorkItemDates(newStartDate, newDueDate);
   416→    };
   417→
   418→    // Update work item via LDS
   419→    async updateWorkItemDates(newStartDate, newDueDate) {
   420→        const fields = {};
   421→        fields[ID_FIELD.fieldApiName] = this.workItem.id;
   422→        fields[START_DATE_FIELD.fieldApiName] = this.formatDateForSalesforce(newStartDate);
   423→        fields[DUE_DATE_FIELD.fieldApiName] = this.formatDateForSalesforce(newDueDate);
   424→
   425→        const recordInput = { fields };
