   427→        try {
   428→            await updateRecord(recordInput);
   429→
   430→            // Publish update event via LMS to trigger refresh in all components
   431→            const message = {
   432→                workItemId: this.workItem.id,
   433→                projectId: this.workItem.projectId,
   434→                source: 'gantt', // Indicate this update came from GANTT drag/resize
   435→                changes: {
   436→                    startDate: fields[START_DATE_FIELD.fieldApiName],
   437→                    dueDate: fields[DUE_DATE_FIELD.fieldApiName]
   438→                }
   439→            };
   440→
   441→            this.notify('workItemUpdated', message);
   442→
   443→            // Also publish refresh message to update other tabs/components
   444→            const refreshMessage = {
   445→                workItemId: this.workItem.id,
   446→                projectId: this.workItem.projectId
   447→            };
   448→            this.notify('refresh', refreshMessage);
   449→
   450→            this.showSuccess('Work item dates updated');
   451→        } catch (error) {
   452→            this.showError(error.body?.message || 'Unknown error', 'Error updating dates');
   453→
   454→            // Publish refresh message via LMS to revert changes
   455→            const refreshMessage = {
   456→                workItemId: this.workItem.id,
   457→                projectId: this.workItem.projectId
   458→            };
   459→            this.notify('refresh', refreshMessage);
   460→        }
   461→    }
   462→
   463→    // Utility methods
   464→    parseLocalDate(dateString) {
   465→        // Parse YYYY-MM-DD as local date (not UTC)
   466→        if (!dateString) {
   467→            return null;
   468→        }
   469→        const [year, month, day] = dateString.split('-');
   470→        return new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
   471→    }
   472→
   473→    formatDate(dateString) {
   474→        if (!dateString) {
   475→            return '-';
   476→        }
   477→        const date = this.parseLocalDate(dateString);
   478→        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
   479→    }
   480→
   481→    formatDateLocal(date) {
   482→        if (!date) {
   483→            return '-';
   484→        }
   485→        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
   486→    }
   487→
   488→    formatDateForSalesforce(date) {
   489→        const year = date.getFullYear();
   490→        const month = String(date.getMonth() + 1).padStart(2, '0');
   491→        const day = String(date.getDate()).padStart(2, '0');
   492→        return `${year}-${month}-${day}`;
