Now I have a complete understanding of the codebase. Let me provide a comprehensive test architecture design.

---

# LWC Test Architecture Design for CGPM

## Executive Summary

After analyzing all 21 LWC components, I have identified the following key testing patterns needed:

1. **Apex Wire Mocking** - 14 components use `@wire` decorators with Apex methods
2. **Lightning Data Service (LDS)** - 6 components use `updateRecord`, `deleteRecord`, or `getRecord`
3. **Lightning Message Service (LMS)** - All components extend `BaseComponent` which subscribes to `WorkItemEventChannel__c`
4. **NavigationMixin** - 3 components use navigation
5. **Module-level Cache** - `dataManager.js` uses `PROJECT_DATA_CACHE` and `INSTANCES` at module level
6. **Custom Events** - Heavy use of bubbling custom events for parent-child communication

---

## File/Folder Structure Proposal

```
force-app/main/default/lwc/
├── __tests__/                          # Shared test infrastructure
│   ├── setup/
│   │   └── jest.setup.js               # Global jest setup (clearCache, etc.)
│   ├── mocks/
│   │   ├── apex/
│   │   │   ├── workItemController.mock.js      # WorkItemController mocks
│   │   │   ├── workItemCreateController.mock.js
│   │   │   ├── timeLogController.mock.js
│   │   │   └── workItemNoteController.mock.js
│   │   ├── lms/
│   │   │   └── messageService.mock.js          # LMS mock utilities
│   │   ├── lds/
│   │   │   └── uiRecordApi.mock.js             # updateRecord/deleteRecord mocks
│   │   └── navigation/
│   │       └── navigationMixin.mock.js         # NavigationMixin mock
│   ├── fixtures/
│   │   ├── workItemWrapper.fixture.js          # WorkItemWrapper test data
│   │   ├── projectDataWrapper.fixture.js       # ProjectDataWrapper test data
│   │   ├── resourceAssignment.fixture.js       # Resource assignment test data
│   │   ├── timeEntry.fixture.js                # Time entry test data
│   │   └── templates.fixture.js                # Template picklist options
│   ├── utils/
│   │   ├── testUtils.js                        # Component creation, event helpers
│   │   ├── assertions.js                       # Custom assertion helpers
│   │   └── domUtils.js                         # Shadow DOM query helpers
│   └── index.js                                # Re-export all test utilities
├── baseComponent/
│   └── __tests__/
│       └── baseComponent.test.js
├── dataManager/
│   ├── dataManager.js                          # Add clearCache() export
│   └── __tests__/
│       └── dataManager.test.js
├── workItemCard/
│   └── __tests__/
│       └── workItemCard.test.js
└── ... (other components follow same pattern)
```

---

## Shared Utility Modules

### 1. Jest Setup (`__tests__/setup/jest.setup.js`)

```javascript
/**
 * Global Jest setup for CGPM LWC tests
 * Configures test environment and imports shared setup
 */

// Import clearCache from dataManager (requires dataManager modification)
import { clearCache } from 'c/dataManager';

// Clear module-level cache before each test
beforeEach(() => {
    // Clear dataManager's PROJECT_DATA_CACHE and INSTANCES
    if (typeof clearCache === 'function') {
        clearCache();
    }

    // Clear localStorage mock
    window.localStorage.clear();

    // Reset all Jest mocks
    jest.clearAllMocks();
});

// Clean up after each test
afterEach(() => {
    // Reset DOM
    while (document.body.firstChild) {
        document.body.removeChild(document.body.firstChild);
    }
});
```

### 2. Test Utilities (`__tests__/utils/testUtils.js`)

```javascript
/**
 * Test utility functions for LWC component testing
 */
import { createElement } from 'lwc';

/**
 * Creates and appends a component to the DOM
 * @param {string} tagName - The component tag name (e.g., 'c-work-item-card')
 * @param {Function} ComponentClass - The component constructor
 * @param {Object} props - Initial public properties
 * @returns {HTMLElement} The created element
 */
export function createComponent(tagName, ComponentClass, props = {}) {
    const element = createElement(tagName, { is: ComponentClass });

    // Set public properties
    Object.keys(props).forEach(key => {
        element[key] = props[key];
    });

    document.body.appendChild(element);
    return element;
}

/**
 * Waits for all pending promises to resolve
 * Use after triggering async operations
 */
export function flushPromises() {
    return new Promise(resolve => setTimeout(resolve, 0));
}

/**
 * Waits for a specific number of microtasks
 * Useful for wire service reactivity
 */
export async function flushMicrotasks(count = 1) {
    for (let i = 0; i < count; i++) {
        await Promise.resolve();
    }
}

/**
 * Simulates a click event on an element
 * @param {HTMLElement} element - Target element
 */
export function click(element) {
    element.dispatchEvent(new MouseEvent('click', { bubbles: true }));
}

/**
 * Simulates input change
 * @param {HTMLElement} input - Input element
 * @param {string} value - New value
 */
export function inputValue(input, value) {
    input.value = value;
    input.dispatchEvent(new CustomEvent('change', { detail: { value } }));
}

/**
 * Creates a mock CustomEvent with detail
 * @param {string} type - Event type
 * @param {Object} detail - Event detail
 */
export function createCustomEvent(type, detail = {}) {
    return new CustomEvent(type, {
        detail,
        bubbles: true,
        composed: true
    });
}

/**
 * Captures dispatched events from a component
 * @param {HTMLElement} element - Component element
 * @param {string} eventName - Event name to capture
 * @returns {Object} Object with captured array and handler
 */
export function captureEvents(element, eventName) {
    const captured = [];
    const handler = (event) => captured.push(event.detail);
    element.addEventListener(eventName, handler);
    return { captured, handler };
}
```

### 3. DOM Query Utilities (`__tests__/utils/domUtils.js`)

```javascript
/**
 * Shadow DOM query utilities for LWC testing
 */

/**
 * Query selector within shadow DOM
 * @param {HTMLElement} element - Component element
 * @param {string} selector - CSS selector
 */
export function shadowQuery(element, selector) {
    return element.shadowRoot.querySelector(selector);
}

/**
 * Query all within shadow DOM
 * @param {HTMLElement} element - Component element
 * @param {string} selector - CSS selector
 */
export function shadowQueryAll(element, selector) {
    return element.shadowRoot.querySelectorAll(selector);
}

/**
 * Finds a button by its label text
 * @param {HTMLElement} element - Component element
 * @param {string} label - Button label text
 */
export function findButtonByLabel(element, label) {
    const buttons = shadowQueryAll(element, 'lightning-button, button');
    return Array.from(buttons).find(btn => 
        btn.label === label || btn.textContent.includes(label)
    );
}

/**
 * Finds an input by its label
 * @param {HTMLElement} element - Component element
 * @param {string} label - Field label
 */
export function findInputByLabel(element, label) {
    const inputs = shadowQueryAll(element, 'lightning-input, lightning-textarea, lightning-combobox');
    return Array.from(inputs).find(input => input.label === label);
}

/**
 * Gets text content from an element
 * @param {HTMLElement} element - Component element
 * @param {string} selector - CSS selector
 */
export function getTextContent(element, selector) {
    const el = shadowQuery(element, selector);
    return el ? el.textContent.trim() : null;
}
```

### 4. Custom Assertions (`__tests__/utils/assertions.js`)

```javascript
/**
 * Custom assertion helpers for CGPM testing
 */
import { shadowQuery, shadowQueryAll } from './domUtils';

/**
 * Asserts that a toast was shown with specific message
 * @param {HTMLElement} element - Component element
 * @param {Object} expected - Expected toast properties { title, message, variant }
 */
export function expectToastShown(mockShowToast, expected) {
    expect(mockShowToast).toHaveBeenCalled();
    const call = mockShowToast.mock.calls[0][0];
    if (expected.title) expect(call.title).toBe(expected.title);
    if (expected.message) expect(call.message).toContain(expected.message);
    if (expected.variant) expect(call.variant).toBe(expected.variant);
}

/**
 * Asserts that a custom event was dispatched
 * @param {Array} capturedEvents - Array from captureEvents()
 * @param {Object} expectedDetail - Expected event detail
 */
export function expectEventDispatched(capturedEvents, expectedDetail) {
    expect(capturedEvents.length).toBeGreaterThan(0);
    const lastEvent = capturedEvents[capturedEvents.length - 1];
    expect(lastEvent).toMatchObject(expectedDetail);
}

/**
 * Asserts component is in loading state
 * @param {HTMLElement} element - Component element
 */
export function expectLoading(element) {
    const spinner = shadowQuery(element, 'lightning-spinner');
    expect(spinner).not.toBeNull();
}

/**
 * Asserts component is not in loading state
 * @param {HTMLElement} element - Component element
 */
export function expectNotLoading(element) {
    const spinner = shadowQuery(element, 'lightning-spinner');
    expect(spinner).toBeNull();
}

/**
 * Asserts work item card displays correct data
 * @param {HTMLElement} element - WorkItemCard element
 * @param {Object} workItem - Expected work item data
 */
export function expectWorkItemDisplayed(element, workItem) {
    expect(getTextContent(element, '.work-item-name')).toBe(workItem.name);
    expect(getTextContent(element, '.status-badge')).toBe(workItem.status);
}
```

---

## Mock Factory Patterns

### 1. Apex Mocks (`__tests__/mocks/apex/workItemController.mock.js`)

```javascript
/**
 * Mock factories for WorkItemController Apex methods
 */
import { createProjectDataWrapper, createWorkItemWrapper } from '../../fixtures/workItemWrapper.fixture';

// Track mock implementations for test assertions
export const mockCalls = {
    getWorkItemsForProject: [],
    getWorkItemWithChildren: [],
    moveWorkItem: [],
    updateWorkItem: []
};

/**
 * Creates a successful getWorkItemsForProject mock
 * @param {Object} data - Optional override data
 */
export function mockGetWorkItemsForProject(data = null) {
    const responseData = data || createProjectDataWrapper();
    return jest.fn().mockResolvedValue(responseData);
}

/**
 * Creates a failing getWorkItemsForProject mock
 * @param {string} message - Error message
 */
export function mockGetWorkItemsForProjectError(message = 'Error loading work items') {
    return jest.fn().mockRejectedValue({
        body: { message }
    });
}

/**
 * Creates wire adapter mock for getWorkItemsForProject
 * Use with @salesforce/sfdx-lwc-jest wire mocking
 */
export function createWireAdapter() {
    let dataCallback = null;
    let errorCallback = null;

    return {
        emit: (data) => {
            if (dataCallback) dataCallback({ data, error: undefined });
        },
        emitError: (error) => {
            if (errorCallback) errorCallback({ data: undefined, error });
        },
        register: (callback) => {
            dataCallback = callback;
        }
    };
}

/**
 * Mock for moveWorkItem Apex method
 */
export function mockMoveWorkItem() {
    return jest.fn().mockImplementation((params) => {
        mockCalls.moveWorkItem.push(params);
        return Promise.resolve();
    });
}

/**
 * Reset all mock call tracking
 */
export function resetMocks() {
    Object.keys(mockCalls).forEach(key => {
        mockCalls[key] = [];
    });
}
```

### 2. LMS Mocks (`__tests__/mocks/lms/messageService.mock.js`)

```javascript
/**
 * Lightning Message Service mock utilities
 */

// Store published messages for assertions
let publishedMessages = [];
let subscriptions = [];

/**
 * Mock publish function
 */
export const mockPublish = jest.fn((context, channel, message) => {
    publishedMessages.push({ context, channel, message });
    // Notify all subscribers
    subscriptions.forEach(sub => {
        if (sub.channel === channel) {
            sub.callback(message);
        }
    });
});

/**
 * Mock subscribe function
 */
export const mockSubscribe = jest.fn((context, channel, callback) => {
    const subscription = { context, channel, callback, id: Date.now() };
    subscriptions.push(subscription);
    return subscription;
});

/**
 * Mock unsubscribe function
 */
export const mockUnsubscribe = jest.fn((subscription) => {
    subscriptions = subscriptions.filter(s => s.id !== subscription.id);
});

/**
 * Simulates receiving an LMS message
 * @param {Object} message - Message payload
 */
export function simulateLmsMessage(message) {
    subscriptions.forEach(sub => sub.callback(message));
}

/**
 * Gets all published messages
 */
export function getPublishedMessages() {
    return [...publishedMessages];
}

/**
 * Gets last published message
 */
export function getLastPublishedMessage() {
    return publishedMessages[publishedMessages.length - 1];
}

/**
 * Asserts a specific message was published
 * @param {string} action - Expected action
 * @param {Object} detailMatcher - Partial object to match against message
 */
export function expectMessagePublished(action, detailMatcher = {}) {
    const message = publishedMessages.find(m => m.message.action === action);
    expect(message).toBeDefined();
    expect(message.message).toMatchObject({ action, ...detailMatcher });
}

/**
 * Reset all LMS mocks
 */
export function resetLmsMocks() {
    publishedMessages = [];
    subscriptions = [];
    mockPublish.mockClear();
    mockSubscribe.mockClear();
    mockUnsubscribe.mockClear();
}

// Default mock implementations for jest.mock
export default {
    publish: mockPublish,
    subscribe: mockSubscribe,
    unsubscribe: mockUnsubscribe,
    MessageContext: jest.fn()
};
```

### 3. LDS Mocks (`__tests__/mocks/lds/uiRecordApi.mock.js`)

```javascript
/**
 * Lightning Data Service mock utilities
 */

// Track all update/delete calls
let updateRecordCalls = [];
let deleteRecordCalls = [];

/**
 * Mock updateRecord that succeeds
 */
export const mockUpdateRecordSuccess = jest.fn((recordInput) => {
    updateRecordCalls.push(recordInput);
    return Promise.resolve({ id: recordInput.fields.Id });
});

/**
 * Mock updateRecord that fails
 * @param {string} message - Error message
 */
export function mockUpdateRecordError(message = 'Update failed') {
    return jest.fn().mockRejectedValue({
        body: { message }
    });
}

/**
 * Mock deleteRecord that succeeds
 */
export const mockDeleteRecordSuccess = jest.fn((recordId) => {
    deleteRecordCalls.push(recordId);
    return Promise.resolve();
});

/**
 * Mock deleteRecord that fails
 * @param {string} message - Error message
 */
export function mockDeleteRecordError(message = 'Delete failed') {
    return jest.fn().mockRejectedValue({
        body: { message }
    });
}

/**
 * Gets all updateRecord calls
 */
export function getUpdateRecordCalls() {
    return [...updateRecordCalls];
}

/**
 * Gets last updateRecord call
 */
export function getLastUpdateRecordCall() {
    return updateRecordCalls[updateRecordCalls.length - 1];
}

/**
 * Asserts updateRecord was called with specific fields
 * @param {Object} expectedFields - Expected fields object
 */
export function expectUpdateRecordCalledWith(expectedFields) {
    const lastCall = getLastUpdateRecordCall();
    expect(lastCall).toBeDefined();
    expect(lastCall.fields).toMatchObject(expectedFields);
}

/**
 * Reset all LDS mocks
 */
export function resetLdsMocks() {
    updateRecordCalls = [];
    deleteRecordCalls = [];
    mockUpdateRecordSuccess.mockClear();
    mockDeleteRecordSuccess.mockClear();
}

export default {
    updateRecord: mockUpdateRecordSuccess,
    deleteRecord: mockDeleteRecordSuccess,
    getRecord: jest.fn(),
    getFieldValue: jest.fn((record, field) => record?.fields?.[field.fieldApiName]?.value)
};
